fn anagram_groups(words: List[String]) -> List[List[String]] {
  let mut groups = Map[String, List[String]]()
  for w in words {
    let sorted = sort_by(w, |c| c)
    groups = map_set(groups, sorted, append(map_get(groups, sorted), w))
  }
  return filter(map_values(groups), |ws| len(ws) > 1)
}

