type Key =
  | Digit(d: Int)
  | Enter
  | Clear

type State =
  | Locked { buffer: String, failures: Int }
  | Open
  | Blocked

fn door_lock(code: String, events: List[Key]) -> String {
  let mut state = Locked { buffer: "", failures: 0 };

  for event in events {
    state = match state {
      Locked { buffer, failures } => match event {
        Digit(d) => {
          let new_buffer = buffer + to_string(d);
          if str_len(new_buffer) > str_len(code) {
            new_buffer.slice(str_len(new_buffer) - str_len(code)..)
          } else {
            new_buffer
          }
        },
        Enter => {
          if new_buffer == code {
            Open
          } else {
            let new_failures = failures + 1;
            if new_failures >= 3 {
              Blocked
            } else {
              Locked { buffer: "", failures: new_failures }
            }
          }
        },
        Clear => Locked { buffer: "", failures }
      },
      Open => match event {
        Enter => Locked { buffer: "", failures: 0 },
        _ => state
      },
      Blocked => state
    };
  }

  match state {
    Locked { .. } => "locked",
    Open => "open",
    Blocked => "blocked"
  }
}

