fn parse_version(version: String) -> Result[List[Int], String] {
  let parts = split(version, ".")
  if len(parts) > 4 {
    return Err("bad version: " + version)
  }
  let parsed_parts = map(parts, |p| {
    let parsed = parse_int(p)
    if parsed.is_none() {
      return Err("bad version: " + version)
    }
    Ok(parsed.unwrap())
  })
  if contains(parsed_parts, Err(_)) {
    return Err("bad version: " + version)
  }
  Ok(map_from(filter(parsed_parts, |p| p.is_ok()), |p| p.unwrap()))
}

fn compare_versions(a: String, b: String) -> Result[Int, String] {
  let a_parts = parse_version(a)
  let b_parts = parse_version(b)
  if a_parts.is_err() {
    return a_parts
  }
  if b_parts.is_err() {
    return b_parts
  }
  let a_list = a_parts.unwrap()
  let b_list = b_parts.unwrap()
  let max_len = max(len(a_list), len(b_list))
  let a_extended = append(a_list, replicate(max_len - len(a_list), 0))
  let b_extended = append(b_list, replicate(max_len - len(b_list), 0))
  for i in range(0, max_len) {
    if a_extended[i] < b_extended[i] {
      return Ok(-1)
    } else if a_extended[i] > b_extended[i] {
      return Ok(1)
    }
  }
  Ok(0)
}

