fn elevator_scan(start: Int, requests: List[Int], direction: String) -> List[Int] {
  let unique_requests = requests |> filter(|r| r != start) |> unique();
  let mut served = if direction == "up" {
    let above = unique_requests |> filter(|r| r > start) |> sort();
    let below = unique_requests |> filter(|r| r < start) |> sort_desc();
    above ++ below
  } else {
    let below = unique_requests |> filter(|r| r < start) |> sort_desc();
    let above = unique_requests |> filter(|r| r > start) |> sort();
    below ++ above
  };
  if contains(served, start) {
    served = served |> filter(|r| r != start);
  }
  return [start] ++ served;
}

