type Meeting {
  start: Int,
  end: Int,
}

fn free_slots(meetings: List[Meeting], day_start: Int, day_end: Int) -> List[(Int, Int)] {
  if day_end <= day_start {
    return []
  }

  let mut sorted_meetings = meetings
    |> sort_by(|m| m.start)
    |> filter(|m| m.end > m.start);

  let mut free_slots = if sorted_meetings[0].start > day_start {
    [(day_start, sorted_meetings[0].start)]
  } else {
    []
  };

  for i in 1..sorted_meetings.len() {
    if sorted_meetings[i].start > sorted_meetings[i - 1].end {
      free_slots.push((sorted_meetings[i - 1].end, sorted_meetings[i].start));
    }
  }

  if sorted_meetings.last().unwrap().end < day_end {
    free_slots.push((sorted_meetings.last().unwrap().end, day_end));
  }

  return free_slots
}

