type Token = 
  | Number(Int)
  | Plus
  | Minus
  | Star
  | Slash
  | LParen
  | RParen

fn tokenize(s: String) -> Result[List[Token], String] {
  let mut tokens = List[Token]()
  let mut i = 0
  while i < str_len(s) {
    let c = s[i]
    if c == ' ' {
      i = i + 1
    } else if c == '+' {
      tokens = append(tokens, Plus)
      i = i + 1
    } else if c == '-' {
      tokens = append(tokens, Minus)
      i = i + 1
    } else if c == '*' {
      tokens = append(tokens, Star)
      i = i + 1
    } else if c == '/' {
      tokens = append(tokens, Slash)
      i = i + 1
    } else if c == '(' {
      tokens = append(tokens, LParen)
      i = i + 1
    } else if c == ')' {
      tokens = append(tokens, RParen)
      i = i + 1
    } else if c >= '0' && c <= '9' {
      let mut num = 0
      while i < str_len(s) && s[i] >= '0' && s[i] <= '9' {
        num = num * 10 + (s[i] - '0')
        i = i + 1
      }
      tokens = append(tokens, Number(num))
    } else {
      return Err("unexpected character: " + to_string(c))
    }
  }
  return Ok(tokens)
}

fn parse_expr(tokens: List[Token]) -> Result[Int, String] {
  let (expr, remaining) = parse_term(tokens)
  if remaining == List[Token]() {
    return expr
  } else {
    return Err("unexpected end")
  }
}

fn parse_term(tokens: List[Token]) -> (Result[Int, String], List[Token]) {
  let (factor, remaining) = parse_factor(tokens)
  let mut result = factor
  while remaining != List[Token]() && (remaining[0] == Star || remaining[0] == Slash) {
    let op = remaining[0]
    remaining = drop(remaining, 1)
    let (factor, remaining) = parse_factor(remaining)
    if op == Star {
      result = Ok(result.unwrap() * factor.unwrap())
    } else {
      if factor.unwrap() == 0 {
        return (Err("division by zero"), List[Token]())
      }
      result = Ok(result.unwrap() / factor.unwrap())
    }
  }
  return (result, remaining)
}

fn parse_factor(tokens: List[Token]) -> (Result[Int, String], List[Token]) {
  if tokens[0] == LParen {
    tokens = drop(tokens, 1)
    let (expr, remaining) = parse_expr(tokens)
    if remaining[0] == RParen {
      return (expr, drop(remaining, 1))
    } else {
      return (Err("unexpected end"), List[Token]())
    }
  } else if tokens[0] == Number {
    return (Ok(tokens[0].unwrap().value), drop(tokens, 1))
  } else {
    return (Err("unexpected end"), List[Token]())
  }
}

fn eval_expr(s: String) -> Result[Int, String] {
  let tokens = tokenize(s)
  if tokens.is_err() {
    return tokens
  }
  let expr = parse_expr(tokens.unwrap())
  if expr.is_err() {
    return expr
  }
  return expr
}

