type Stock {
  sku: String,
  qty: Int,
}

type Txn {
  sku: String,
  delta: Int,
}

fn inventory_ledger(stock: List[Stock], txns: List[Txn]) -> Result[List[Stock], String] {
  var ledger = map_from(stock.map(|s| (s.sku, s.qty)))
  for (i, txn) in enumerate(txns) {
    if !map_contains(ledger, txn.sku) {
      return Err(format("txn {}: unknown sku {}", i + 1, txn.sku))
    }
    var new_qty = ledger[txn.sku] + txn.delta
    if new_qty < 0 {
      return Err(format("txn {}: {} would go negative", i + 1, txn.sku))
    }
    map_set(ledger, txn.sku, new_qty)
  }
  let result = ledger
    |> map_to_list
    |> filter(|(_, qty)| qty > 0)
    |> sort_by(|(sku, _)| sku)
  return Ok(result)
}

