fn count_values(xs: List[Int]) -> Map[Int, Int] {
  xs
    |> fold({}, |acc, x| {
      let count = map_get(acc, x) |> unwrap_or(0) + 1
      map_set(acc, x, count)
    })
}

fn k_most_frequent(xs: List[Int], k: Int) -> List[(Int, Int)] {
  if k <= 0 {
    return []
  }

  let counts = count_values(xs)
  let mut items: List[Count] = counts
    |> map(|(value, count)| { { value, count } })
    |> sort_by(|a, b| {
      if a.count != b.count {
        b.count - a.count
      } else {
        a.value - b.value
      }
    })

  items
    |> take(k)
    |> map(|item| (item.value, item.count))
}

