      let (points, goal_difference, goals) = match map_get(table, team) {
        Some((p, gd, g)) => (p, gd, g),
        None => (0, 0, 0),
      }
      map_set(table, team, (points + (if goals_for > goals_against { 3 } else if goals_for == goals_against { 1 } else { 0 }), goal_difference + goals_for - goals_against, goals + goals_for))
    }

    update(m.home, m.home_goals, m.away_goals)
