fn lis_length(xs: List[Int]) -> (Int, Int) {
  if xs == [] {
    return (0, 0)
  }

  let n = len(xs)
  let lengths = map(xs, |x| 1)
  let counts = map(xs, |x| 1)

  for i in range(1, n) {
    for j in range(0, i) {
      if xs[i] > xs[j] {
        if lengths[j] + 1 > lengths[i] {
          lengths[i] = lengths[j] + 1
          counts[i] = counts[j]
        } else if lengths[j] + 1 == lengths[i] {
          counts[i] = counts[i] + counts[j]
        }
      }
    }
  }

  let max_length = max(lengths)
  let max_count = sum(filter(counts, |c| c == max_length))

  return (max_length, max_count)
}

