  effects: io
  requires: amount >= 0
  ensures: result == None || (result != None && (result.0 == 0 || (result.0 < min_coins(coins, amount - 1).unwrap_or((amount, [])).0 && (result.0 == min_coins(coins, amount - 1).unwrap_or((amount, [])).0 || result.1 > min_coins(coins, amount - 1).unwrap_or((amount, [])).1))))
{
  if amount < 0 {
    return None
  }
  if amount == 0 {
    return Some((0, []))
  }
  var best: Option[(Int, List[Int])] = None
  for coin in coins {
    if coin > amount {
      continue
