      var (n, used) = rest.unwrap()
      var total = n + 1
      var new_used = append(used, coin)
      if best == None || total < best.unwrap().0 || (total == best.unwrap().0 && new_used > best.unwrap().1) {
        best = Some((total, new_used))
      }
    }
  }
  return best
}

