fn parse_duration(s: String) -> Result[Int, String] {
  if str_len(s) == 0 {
    return Err("empty".to_string());
  }

  let mut seconds = 0;
  let mut h_found = false;
  let mut m_found = false;
  let mut s_found = false;

  let mut i = 0;
  while i < str_len(s) {
    let mut num = 0;
    let mut j = i;
    while j < str_len(s) && s[j] >= '0' && s[j] <= '9' {
      num = num * 10 + (s[j] as u8 - '0' as u8) as Int;
      j += 1;
    }

    if j == i {
      return Err(format!("missing number before {}", s[j]));
    }

    if j < str_len(s) {
      let unit = s[j];
      if unit == 'h' {
        if h_found || m_found || s_found {
          return Err(format!("unit out of order: {}", unit));
        }
        seconds += num * 3600;
        h_found = true;
      } else if unit == 'm' {
        if m_found || s_found {
          return Err(format!("unit out of order: {}", unit));
        }
        seconds += num * 60;
        m_found = true;
      } else if unit == 's' {
        if s_found {
          return Err(format!("unit out of order: {}", unit));
        }
        seconds += num;
        s_found = true;
      } else {
        return Err(format!("unknown unit: {}", unit));
      }
      i = j + 1;
    } else {
      return Err("missing unit".to_string());
    }
  }

  Ok(seconds)
}

