type Cmd =
  | Forward(steps: Int)
  | TurnLeft
  | TurnRight

fn robot_walk(cmds: List[Cmd], obstacles: List[(Int, Int)]) -> (Int, Int, String) {
  var x = 0
  var y = 0
  var direction = "N"

  for cmd in cmds {
    match cmd {
      Forward(steps) => {
        for _ in 0..steps {
          var next_x = x
          var next_y = y
          match direction {
            "N" => next_y = next_y + 1,
            "E" => next_x = next_x + 1,
            "S" => next_y = next_y - 1,
            "W" => next_x = next_x - 1,
            _ => assert(false),
          }
          if !contains(obstacles, (next_x, next_y)) {
            x = next_x
            y = next_y
          } else {
            break
          }
        }
      },
      TurnLeft => {
        match direction {
          "N" => direction = "W",
          "E" => direction = "N",
          "S" => direction = "E",
          "W" => direction = "S",
          _ => assert(false),
        }
      },
      TurnRight => {
        match direction {
          "N" => direction = "E",
          "E" => direction = "S",
          "S" => direction = "W",
          "W" => direction = "N",
          _ => assert(false),
        }
      },
    }
  }

  return (x, y, direction)
}

