type Session {
  user: String,
  kind: String,
  time: Int,
}

fn session_totals(events: List[Session]) -> List[(String, Int)] {
  let mut totals = Map[String, Int] {}
  let mut open_sessions = Map[String, Int] {}

  for event in events {
    match event.kind {
      "login" => {
        if !open_sessions.contains(event.user) {
          open_sessions.set(event.user, event.time)
        }
      },
      "logout" => {
        if open_sessions.contains(event.user) {
          let start_time = open_sessions.get(event.user)
          let duration = event.time - start_time
          totals.set(event.user, totals.get_or(event.user, 0) + duration)
          open_sessions.remove(event.user)
        }
      },
    }
  }

  for (user, start_time) in open_sessions {
    let duration = events.last().unwrap().time - start_time
    totals.set(user, totals.get_or(user, 0) + duration)
  }

  return totals.keys()
    |> sort_by(|u| u)
    |> map(|u| (u, totals.get(u)))
}

