type EditOp =
  | Insert(text: String)
  | Delete(n: Int)
  | Left(n: Int)
  | Right(n: Int)
  | Undo

fn text_editor(ops: List[EditOp]) -> String {
  var text = ""
  var cursor = 0
  var history = []

  for op in ops {
    match op {
      Insert(t) => {
        history = (text, cursor) :: history
        text = text[0, cursor] + t + text[cursor, len(text)]
        cursor = cursor + len(t)
      },
      Delete(n) => {
        history = (text, cursor) :: history
        let remove = min(n, cursor)
        text = text[0, cursor - remove] + text[cursor, len(text)]
        cursor = cursor - remove
      },
      Left(n) => {
        history = (text, cursor) :: history
        cursor = max(0, cursor - n)
      },
      Right(n) => {
        history = (text, cursor) :: history
        cursor = min(len(text), cursor + n)
      },
      Undo => {
        if len(history) > 0 {
          let (prev_text, prev_cursor) = history[0]
          history = history[1, len(history)]
          text = prev_text
          cursor = prev_cursor
        }
      },
    }
  }

  return text
}

