type Board = List[String]

fn tic_tac_toe(board: Board) -> String {
  let rows = board
  let cols = transpose(rows)
  let diags = [rows[0][0] + rows[1][1] + rows[2][2], rows[0][2] + rows[1][1] + rows[2][0]]
  let all_lines = rows ++ cols ++ diags

  let count_marks(line: String, mark: String) -> Int {
    return line.filter(|c| c == mark).len()
  }

  let count_x = all_lines.map(|line| count_marks(line, "X")).sum()
  let count_o = all_lines.map(|line| count_marks(line, "O")).sum()

  if abs(count_x - count_o) > 1 || (count_x < count_o && count_o != 0) {
    return "invalid"
  }

  let has_line(line: String) -> Bool {
    return line == "XXX" || line == "OOO"
  }

  let x_wins = all_lines.any(|line| has_line(line) && count_marks(line, "X") == 3)
  let o_wins = all_lines.any(|line| has_line(line) && count_marks(line, "O") == 3)

  if x_wins && count_x != count_o + 1 {
    return "invalid"
  }

  if o_wins && count_x != count_o {
    return "invalid"
  }

  if x_wins {
    return "X wins"
  }

  if o_wins {
    return "O wins"
  }

  if board.map(|row| row.len()).sum() == 9 {
    return "draw"
  }

  return "in progress"
}

