def age_histogram(people: list[Person], width: int) -> Ok[list[tuple[str, int]]] | Err:
    if width < 1:
        return Err(ok=False, error="bad width")
    age_counts: dict[int, int] = {}
    for person in people:
        if person["age"] < 0:
            return Err(ok=False, error=f"negative age: {person['name']}")
        bucket = person["age"] // width
        age_counts[bucket] = age_counts.get(bucket, 0) + 1
    result = []
    for bucket in sorted(age_counts.keys()):
        label = f"{bucket * width}-{(bucket + 1) * width - 1}"
        result.append((label, age_counts[bucket]))
    return Ok(ok=True, value=result)

