fn tennis_score(points: String) -> String {
  let mut a_points = 0;
  let mut b_points = 0;
  let mut game_won = false;

  for point in points.chars() {
    if point == 'A' {
      a_points += 1;
    } else if point == 'B' {
      b_points += 1;
    } else {
      return "error: bad point".to_string();
    }

    if a_points >= 4 && a_points - b_points >= 2 {
      game_won = true;
      return format!("game A");
    } else if b_points >= 4 && b_points - a_points >= 2 {
      game_won = true;
      return format!("game B");
    } else if a_points >= 3 && b_points >= 3 {
      if a_points == b_points {
        return "deuce".to_string();
      } else if a_points - b_points == 1 {
        return "advantage A".to_string();
      } else if b_points - a_points == 1 {
        return "advantage B".to_string();
      }
    }
  }

  if game_won {
    return "error: point after game".to_string();
  }

  format!("{}-{}", point_name(a_points), point_name(b_points))
}

