fn vending_machine(events: List[Event]) -> List[String] {
  var credit = 0
  var messages = List[String]()

  for event in events {
    match event {
      Coin(c) => {
        if c == 5 || c == 10 || c == 25 || c == 100 {
          credit = credit + c
        } else {
          messages = messages ++ ["reject " + to_string(c)]
        }
      },
      Select(p) => {
        if credit >= p {
          messages = messages ++ ["vend " + to_string(p) + " change " + to_string(credit - p)]
          credit = 0
        } else {
          messages = messages ++ ["insufficient " + to_string(credit)]
        }
      },
      Refund => {
        if credit > 0 {
          messages = messages ++ ["refund " + to_string(credit)]
          credit = 0
        }
      },
    }
  }

  if credit > 0 {
    messages = messages ++ ["refund " + to_string(credit)]
  }

  return messages
}

