def bracket_depth(s: str) -> Ok[int] | Err:
    stack = []
    max_depth = 0
    current_depth = 0

    for i, char in enumerate(s):
        if char in "([{":
            stack.append(char)
            current_depth += 1
            max_depth = max(max_depth, current_depth)
        elif char in ")]}":
            if not stack:
                return Err({"ok": False, "error": f"mismatch at {i}"})
            expected = stack.pop()
            if (char == ')' and expected != '(') or \
               (char == ']' and expected != '[') or \
               (char == '}' and expected != '{'):
                return Err({"ok": False, "error": f"mismatch at {i}"})
            current_depth -= 1

    if stack:
        return Err({"ok": False, "error": "unclosed at end"})

    return Ok({"ok": True, "value": max_depth})

