def parse_version(version: str) -> Ok[list[int]] | Err:
    parts = version.split('.')
    parsed_parts = []
    for part in parts:
        if not part.isdigit():
            return Err(ok=False, error=f"bad version: {version}")
        parsed_parts.append(int(part))
    return Ok(ok=True, value=parsed_parts)

def compare_versions(a: str, b: str) -> Ok[int] | Err:
    result_a = parse_version(a)
    if not result_a['ok']:
        return result_a
    result_b = parse_version(b)
    if not result_b['ok']:
        return result_b

    parts_a = result_a['value']
    parts_b = result_b['value']
    max_length = max(len(parts_a), len(parts_b))
    parts_a += [0] * (max_length - len(parts_a))
    parts_b += [0] * (max_length - len(parts_b))

    for i in range(max_length):
        if parts_a[i] < parts_b[i]:
            return Ok(ok=True, value=-1)
        elif parts_a[i] > parts_b[i]:
            return Ok(ok=True, value=1)

    return Ok(ok=True, value=0)

