Key = Digit | Enter | Clear

def door_lock(code: str, events: list[Key]) -> str:
    buffer: list[int] = []
    failure_count = 0
    state: Literal["locked", "open", "blocked"] = "locked"

    for event in events:
        if state == "locked":
            if event["kind"] == "Digit":
                buffer.append(event["d"])
                if len(buffer) > len(code):
                    buffer.pop(0)
            elif event["kind"] == "Clear":
                buffer.clear()
            elif event["kind"] == "Enter":
                if buffer == [int(d) for d in code]:
                    state = "open"
                    failure_count = 0
                else:
                    failure_count += 1
                    if failure_count == 3:
                        state = "blocked"
                buffer.clear()
        elif state == "open":
            if event["kind"] == "Enter":
                state = "locked"
        elif state == "blocked":
            pass

    return state

