def heading_numbers(lines: list[str]) -> list[str]:
    counters = [0, 0, 0]
    result = []
    for line in lines:
        if line.startswith("#") and len(line) > 1 and line[1].isspace():
            level = line.count("#")
            if level > 3:
                continue
            title = line[level + 1:].strip()
            if title:
