    start: int
    end: int

def free_slots(meetings: list[Meeting], day_start: int, day_end: int) -> list[tuple[int, int]]:
    if day_end <= day_start:
        return []

    # Sort meetings by start time, and by end time if start times are equal
    meetings.sort(key=lambda m: (m['start'], m['end']))

    free_slots = []
    current_end = day_start

    for meeting in meetings:
        if meeting['start'] > current_end:
            free_slots.append((current_end, meeting['start']))
        current_end = max(current_end, meeting['end'])

    if current_end < day_end:
        free_slots.append((current_end, day_end))

    return free_slots

