def eval_expr(s: str) -> Ok[int] | Err:
    s = s.replace(" ", "")
    result, error = parse_expr(s, 0)
    if error:
        return Err(error=error)
    return Ok(value=result)

def parse_expr(s: str, pos: int) -> tuple[int, str]:
    result, pos = parse_term(s, pos)
    while pos < len(s) and s[pos] in "+-":
        op = s[pos]
        pos += 1
        next_result, pos = parse_term(s, pos)
        if op == "+":
            result += next_result
        else:
            result -= next_result
    return result, pos

def parse_term(s: str, pos: int) -> tuple[int, str]:
    result, pos = parse_factor(s, pos)
    while pos < len(s) and s[pos] in "*/":
        op = s[pos]
        pos += 1
        next_result, pos = parse_factor(s, pos)
        if op == "*":
            result *= next_result
        else:
            if next_result == 0:
                return 0, "division by zero"
            result //= next_result
    return result, pos

def parse_factor(s: str, pos: int) -> tuple[int, str]:
    if pos < len(s) and s[pos] == "(":
        pos += 1
        result, pos = parse_expr(s, pos)
        if pos < len(s) and s[pos] == ")":
            pos += 1
            return result, pos
        else:
            return 0, "expected )"
    elif pos < len(s) and s[pos].isdigit():
        start = pos
        while pos < len(s) and s[pos].isdigit():
            pos += 1
        return int(s[start:pos]), pos
    else:
        return 0, "unexpected end" if pos == len(s) else f"unexpected character: {s[pos]}"

# Rationale:
# - The function `eval_expr` removes spaces and then calls `parse_expr` to evaluate the expression.
# - `parse_expr` parses the expression and returns the result or an error.
# - `parse_term` and `parse_factor` handle the parsing of different parts of the expression, respectively.
# - The operators are handled with left-to-right associativity and correct precedence.
# - Division truncates toward zero.
# - Syntax errors are detected and reported appropriately.

