def flatten_nested(s: str) -> Ok[tuple[list[int], int]] | Err:
    s = s.replace(" ", "")
    if not s.startswith("[") or not s.endswith("]"):
        return Err(ok=False, error="invalid at 0")

    def parse_element(i: int) -> tuple[int, int]:
        if s[i] == "[":
            depth = 1
            j = i + 1
            while j < len(s):
                if s[j] == "[":
                    depth += 1
                elif s[j] == "]":
                    depth -= 1
                elif s[j] == "," and depth == 1:
                    break
                j += 1
            return parse_list(i, j)
        elif s[i] == "-":
            j = i + 1
            while j < len(s) and s[j].isdigit():
                j += 1
            return int(s[i:j]), j
        else:
            j = i
            while j < len(s) and s[j].isdigit():
                j += 1
            return int(s[i:j]), j

    def parse_list(i: int, j: int) -> tuple[list[int], int]:
        result = []
        depth = 1
        while i < j:
            if s[i] == "[":
                depth += 1
            elif s[i] == "]":
                depth -= 1
            elif s[i] == "," and depth == 1:
                i += 1
                continue
            element, i = parse_element(i)
            result.append(element)
        return result, i

    try:
        result, end = parse_list(1, len(s) - 1)
        if end != len(s) - 1:
            return Err(ok=False, error=f"invalid at {end}")
        return Ok(ok=True, value=(result, 1))
    except (IndexError, ValueError):
        return Err(ok=False, error=f"invalid at {end}")

