def parking_fees(events: list[Park]) -> list[tuple[str, int]]:
    parked: dict[str, int] = {}
    fees: dict[str, int] = {}

    for event in events:
        if event["kind"] == "Arrive":
            if event["plate"] not in parked:
                parked[event["plate"]] = event["minute"]
        elif event["kind"] == "Leave":
            if event["plate"] in parked:
                start = parked[event["plate"]]
                duration = event["minute"] - start
                if duration > 30:
                    fee = 200 * ((duration - 30) // 60 + 1)
                    fee = min(fee, 1000)
                    fees[event["plate"]] = fees.get(event["plate"], 0) + fee
                del parked[event["plate"]]

    return sorted(fees.items())

