    settings: list[Setting] = []
    current_section: str = ""
    line_number: int = 0

    for line in lines:
        line_number += 1
        line = line.strip()
        if not line or line.startswith("#"):
            continue
        if line.startswith("["):
            if not line.endswith("]"):
                return Err({"ok": False, "error": f"line {line_number}: bad header"})
            section_name = line[1:-1].strip()
            if not section_name:
                return Err({"ok": False, "error": f"line {line_number}: bad header"})
            current_section = section_name
        else:
            if "=" not in line:
                return Err({"ok": False, "error": f"line {line_number}: missing ="})
            key, value = line.split("=", 1)
            key = key.strip()
            value = value.strip()
            if not key:
                return Err({"ok": False, "error": f"line {line_number}: empty key"})
            settings.append({"section": current_section, "key": key, "value": value})

    return Ok({"ok": True, "value": settings})

