def parse_csv_line(s: str) -> Ok[list[str]] | Err:
    result: list[str] = []
    i = 0
    while i < len(s):
        if s[i] == '"':
            i = parse_quoted_field(s, i, result)
            if i == -1:
                return Err(ok=False, error="unterminated quote")
        else:
            i = parse_unquoted_field(s, i, result)
            if i == -1:
                return Err(ok=False, error=f"expected comma at {i - 1}")
    result.append("")
    return Ok(ok=True, value=result)

def parse_quoted_field(s: str, i: int, result: list[str]) -> int:
    i += 1
    start = i
    while i < len(s) and s[i] != '"':
        if s[i] == '"':
            i += 1
        i += 1
    if i == len(s):
        return -1
    result.append(s[start:i].replace('""', '"'))
    i += 1
    return i

def parse_unquoted_field(s: str, i: int, result: list[str]) -> int:
    start = i
    while i < len(s) and s[i] != ',':
        i += 1
    result.append(s[start:i])
    return i

