from typing import TypedDict

class Contact(TypedDict):
    name: str
    email: str
    phone: str

def merge_contacts(contacts: list[Contact]) -> list[Contact]:
    if not contacts:
        return []

    contact_map = {contact['email']: contact for contact in contacts}
    visited = set()

    def find_representative(email: str) -> str:
        while email in contact_map and contact_map[email]['email'] != email:
            email = contact_map[email]['email']
        return email

    def merge_representative(email: str) -> None:
        representative = find_representative(email)
        for contact in contacts:
            if contact['email'] == representative:
                for field in contact_map[representative]:
                    if contact[field] == "":
                        contact[field] = contact_map[representative][field]

    for contact in contacts:
        if contact['email'] not in visited:
            visited.add(contact['email'])
            representative = find_representative(contact['email'])
            merge_representative(representative)

    return [contact for contact in contacts if contact['email'] in visited]

