def parse_ipv4(s: str) -> Ok[int] | Err:
    parts = s.split(".")
    if len(parts) != 4:
        return Err(ok=False, error="expected 4 parts")

    def is_valid_part(part: str) -> bool:
        if not part.isdigit() or not 0 <= int(part) <= 255:
            return False
        if len(part) > 1 and part[0] == "0":
            return False
        return True

    for part in parts:
        if not is_valid_part(part):
            return Err(ok=False, error=f"bad part: {part}")

    a, b, c, d = map(int, parts)
    value = a * 16777216 + b * 65536 + c * 256 + d
    return Ok(ok=True, value=value)

