def pig_latin(s: str) -> str:
    def translate(word: str) -> str:
        vowels = "aeiou"
        if word[0] in vowels or (word[0] == 'y' and len(word) > 1 and word[1] not in vowels):
            return word + "way"
        else:
            for i, char in enumerate(word):
                if char in vowels or (char == 'y' and i > 0):
                    return word[i:] + word[:i] + "ay"
            return word + "ay"

    return " ".join(translate(word) for word in s.split())

# Rationale:
# - The function `translate` handles the conversion of a single word to Pig Latin.
# - It checks if the word starts with a vowel or 'y' (not followed by a vowel) and appends "way" accordingly.
# - If the word does not start with a vowel or 'y', it finds the first vowel and moves the prefix before it to the end, appending "ay".
# - The main function `pig_latin` splits the input string into words, applies `translate` to each, and joins them back with spaces.

