def robot_walk(cmds: list[Cmd], obstacles: list[tuple[int, int]]) -> tuple[int, int, str]:
    x, y = 0, 0
    direction = "N"
    for cmd in cmds:
        if cmd["kind"] == "TurnLeft":
            direction = {"N": "W", "W": "S", "S": "E", "E": "N"}[direction]
        elif cmd["kind"] == "TurnRight":
            direction = {"N": "E", "E": "S", "S": "W", "W": "N"}[direction]
        else:
            steps = cmd["steps"]
            while steps > 0:
                if direction == "N":
                    if (x, y + 1) not in obstacles:
                        y += 1
                    else:
                        break
                elif direction == "E":
                    if (x + 1, y) not in obstacles:
                        x += 1
                    else:
                        break
                elif direction == "S":
                    if (x, y - 1) not in obstacles:
                        y -= 1
                    else:
                        break
                elif direction == "W":
                    if (x - 1, y) not in obstacles:
                        x -= 1
                    else:
                        break
                steps -= 1
    return x, y, direction

