    kind: Literal["Jmp"]
    target: int

class Print(TypedDict):
    kind: Literal["Print"]

class Halt(TypedDict):
    kind: Literal["Halt"]

Instr = Push | Pop | Add | Sub | Mul | Dup | Swap | Jz | Jmp | Print | Halt

def stack_vm(prog: list[Instr]) -> Ok[list[int]] | Err:
    stack: list[int] = []
    output: list[int] = []
    pc: int = 0
    steps: int = 0
    max_steps: int = 1000

    while pc < len(prog) and steps < max_steps:
        instr = prog[pc]
        steps += 1

        if instr["kind"] == "Push":
            stack.append(instr["n"])
        elif instr["kind"] == "Pop":
            if not stack:
                return Err({"ok": False, "error": f"stack underflow at {pc}"})
            stack.pop()
        elif instr["kind"] == "Add":
            if len(stack) < 2:
                return Err({"ok": False, "error": f"stack underflow at {pc}"})
            b = stack.pop()
            a = stack.pop()
            stack.append(a + b)
        elif instr["kind"] == "Sub":
            if len(stack) < 2:
                return Err({"ok": False, "error": f"stack underflow at {pc}"})
            b = stack.pop()
            a = stack.pop()
            stack.append(a - b)
        elif instr["kind"] == "Mul":
            if len(stack) < 2:
                return Err({"ok": False, "error": f"stack underflow at {pc}"})
            b = stack.pop()
            a = stack.pop()
            stack.append(a * b)
        elif instr["kind"] == "Dup":
            if not stack:
                return Err({"ok": False, "error": f"stack underflow at {pc}"})
            stack.append(stack[-1])
        elif instr["kind"] == "Swap":
            if len(stack) < 2:
                return Err({"ok": False, "error": f"stack underflow at {pc}"})
            stack[-1], stack[-2] = stack[-2], stack[-1]
        elif instr["kind"] == "Jz":
            if len(stack) < 1:
                return Err({"ok": False, "error": f"stack underflow at {pc}"})
            if stack[-1] == 0:
                pc = instr["target"]
            else:
                pc += 1
        elif instr["kind"] == "Jmp":
            pc = instr["target"]
        elif instr["kind"] == "Print":
            if not stack:
                return Err({"ok": False, "error": f"stack underflow at {pc}"})
            output.append(stack.pop())
        elif instr["kind"] == "Halt":
            break

    if steps >= max_steps:
        return Err({"ok": False, "error": "step limit exceeded"})

    return Ok({"ok": True, "value": output})

