def text_editor(ops: list[EditOp]) -> str:
    text = ""
    cursor = 0
    history: list[tuple[str, int]] = []

    for op in ops:
        if op["kind"] == "Insert":
            history.append((text, cursor))
            text = text[:cursor] + op["text"] + text[cursor:]
            cursor += len(op["text"])
        elif op["kind"] == "Delete":
            history.append((text, cursor))
            n = min(op["n"], cursor)
            text = text[:cursor - n] + text[cursor:]
            cursor -= n
        elif op["kind"] == "Left":
            history.append((text, cursor))
            cursor = max(0, cursor - op["n"])
        elif op["kind"] == "Right":
            history.append((text, cursor))
            cursor = min(len(text), cursor + op["n"])
        elif op["kind"] == "Undo":
            if history:
                text, cursor = history.pop()

    return text

