def tic_tac_toe(board: list[str]) -> str:
    def check_line(line: str) -> bool:
        return line == "XXX" or line == "OOO"

    def check_winner(board: list[str]) -> str:
        # Check rows
        for row in board:
            if check_line(row):
                return "X wins" if row == "XXX" else "O wins"
        # Check columns
        for col in range(3):
            if check_line("".join(board[row][col] for row in range(3))):
                return "X wins" if board[0][col] == "X" else "O wins"
        # Check diagonals
        if check_line("".join(board[i][i] for i in range(3))):
            return "X wins" if board[0][0] == "X" else "O wins"
        if check_line("".join(board[i][2 - i] for i in range(3))):
            return "X wins" if board[0][2] == "X" else "O wins"
        return "draw" if all(cell != "." for row in board for cell in row) else "in progress"

    x_count = sum(row.count("X") for row in board)
    o_count = sum(row.count("O") for row in board)

    if abs(x_count - o_count) > 1:
        return "invalid"
    if x_count < o_count:
        return "invalid"
    if check_winner(board) != "in progress":
        return check_winner(board)
    return "in progress"

