def session_totals(events: list[Session]) -> list[tuple[str, int]]:
    user_sessions: dict[str, dict[str, int]] = {}
    for event in events:
        user = event['user']
        if event['kind'] == 'login':
            if user not in user_sessions or user_sessions[user]['kind'] == 'logout':
                user_sessions[user] = {'kind': 'login', 'time': event['time']}
        elif event['kind'] == 'logout':
            if user in user_sessions and user_sessions[user]['kind'] == 'login':
                login_time = user_sessions[user]['time']
                logout_time = event['time']
                if user not in user_sessions:
                    user_sessions[user] = {'time': 0}
                user_sessions[user]['time'] += logout_time - login_time
                del user_sessions[user]
    result = [(user, session['time']) for user, session in sorted(user_sessions.items())]
    return result

