def poker_hand(cards: list[str]) -> HandCategory:
    if len(cards) != 5 or len(set(cards)) != 5:
        return "invalid"

    ranks = sorted([rank(card) for card in cards])
    suits = [suit(card) for card in cards]

    if all(s == suits[0] for s in suits):
        if is_straight(ranks):
            return "straight flush"
        else:
            return "flush"

    rank_counts = {rank: ranks.count(rank) for rank in set(ranks)}
    if 4 in rank_counts.values():
        return "four of a kind"
    elif 3 in rank_counts.values() and 2 in rank_counts.values():
        return "full house"
    elif is_straight(ranks):
        return "straight"
    elif 3 in rank_counts.values():
        return "three of a kind"
    elif list(rank_counts.values()).count(2) == 2:
        return "two pair"
    elif 2 in rank_counts.values():
        return "one pair"
    else:
        return "high card"

