    return card[0]

def suit(card: Card) -> Suit:
    return card[1]

def is_straight(ranks: list[Rank]) -> bool:
    rank_values = [ranks.index(rank) for rank in ranks]
    return all(rank_values[i] + 1 == rank_values[i + 1] for i in range(4))

