def wrap_text(s: str, width: int) -> list[str]:
    words = s.strip().split()
    lines = []
    current_line: list[str] = []
    current_length = 0

    for word in words:
        if len(word) > width:
            if current_line:
                lines.append(' '.join(current_line))
                current_line = []
                current_length = 0
            lines.append(word)
        elif current_length + len(word) + (1 if current_line else 0) <= width:
            current_line.append(word)
            current_length += len(word) + (1 if current_line else 0)
        else:
            lines.append(' '.join(current_line))
            current_line = [word]
            current_length = len(word)

    if current_line:
        lines.append(' '.join(current_line))

    return lines

fn anagram_groups(words: List[String]) -> List[List[String]] {
  let mut groups = Map[String, List[String]]()
  for word in words {
    let sorted = sort_by(word, |c| c)
    groups = match map_get(groups, sorted) {
      Some(list) => map_set(groups, sorted, append(list, word)),
      None => map_set(groups, sorted, [word]),
    }
  }
  return filter(values(groups), |list| len(list) > 1)
}

