type Person {
  name: String,
  age: Int,
}

fn age_histogram(people: List[Person], width: Int) -> Result[List[(String, Int)], String] {
  if width < 1 {
    return Err("bad width".to_string());
  }
  let mut counts = Map::new();
  for p in people {
    if p.age < 0 {
      return Err(format!("negative age: {}", p.name));
    }
    let bucket = p.age / width * width;
    let count = counts.get(bucket).unwrap_or(0);
    counts.set(bucket, count + 1);
  }
  let mut result = List::new();
  let mut min_bucket = i32::MAX;
  let mut max_bucket = i32::MIN;
  for (bucket, &count) in counts {
    if bucket < min_bucket {
      min_bucket = bucket;
    }
    if bucket > max_bucket {
      max_bucket = bucket;
    }
    result.append((format!("{}-{}", bucket, bucket + width - 1), count));
  }
  for bucket in (min_bucket..=max_bucket).step_by(width) {
    if !counts.contains(bucket) {
      result.append((format!("{}-{}", bucket, bucket + width - 1), 0));
    }
  }
  Ok(result)
}

