fn bowling_score(rolls: List[Int]) -> Result[Int, String] {
  if any(|r| r < 0 || r > 10) {
    return Err("invalid roll")
  }

  let mut score = 0
  let mut i = 0

  for frame in 0..10 {
    if frame < 9 {
      if rolls[i] == 10 {
        score = score + 10 + rolls[i + 1] + rolls[i + 2]
        i = i + 1
      } else {
        if rolls[i] + rolls[i + 1] > 10 {
          return Err(format!("too many pins in frame {}", frame + 1))
        }
        score = score + rolls[i] + rolls[i + 1]
        i = i + 2
      }
    } else {
      if rolls[i] == 10 {
        if rolls[i + 1] == 10 {
          if rolls[i + 2] == 10 {
            score = score + 30
          } else {
            score = score + 20 + rolls[i + 2]
          }
        } else {
          if rolls[i + 1] + rolls[i + 2] > 10 {
            return Err("too many pins in frame 10")
          }
          score = score + 10 + rolls[i + 1] + rolls[i + 2]
        }
        i = i + 1
      } else {
        if rolls[i] + rolls[i + 1] > 10 {
          return Err("too many pins in frame 10")
        }
        score = score + rolls[i] + rolls[i + 1]
        if rolls[i] + rolls[i + 1] == 10 {
          score = score + rolls[i + 2]
        }
        i = i + 2
      }
    }
  }

  if i != rolls.len() {
    return Err("too many rolls")
  }

  return Ok(score)
}

