type Job {
  name: String,
  deps: List[String],
}

fn build_order(jobs: List[Job]) -> Result[List[String], String] {
  let job_map = jobs
    |> map(|j| (j.name, j.deps))
    |> map_from();

  let mut order = [];
  let mut placed = [];
  let mut remaining = jobs;

  while remaining.len() > 0 {
    let mut next = null;
    for j in remaining {
      let can_place = j.deps
        |> all(|d| job_map[d].len() == 0 || placed.contains(job_map[d][0]));
      if can_place {
        next = j;
        break;
      }
    }

    if next == null {
      return Err("cycle detected".to_string());
    }

    order.push(next.name);
    placed.push(next.name);
    remaining = remaining
      |> filter(|j| j.name != next.name)
      |> map(|j| Job { name: j.name, deps: j.deps.filter(|d| d != next.name) });
  }

  Ok(order)
}

