fn coverage_gaps(shifts: List[Shift], required: Int) -> List[Int] {
  let hours = range(0, 24)
  let coverage = map(hours, |h| {
    let workers = filter(shifts, |s| s.start_hour <= h && h < s.end_hour)
    let unique_workers = map(workers, |s| s.worker)
    set(unique_workers)  // Remove unnecessary return statement
  })
  let gaps = filter(hours, |h| len(coverage[h]) < required)
  sort(gaps)
}

