fn parse_version(version: String) -> Result[String, String] {
  let parts = split(version, ".");
  if len(parts) > 4 {
    return Err(format!("bad version: {}", version));
  }
  let mut parsed_parts = [];
  for p in parts {
    let num = parse_int(p);
    if num.is_none() {
      return Err(format!("bad version: {}", version));
    }
    append(parsed_parts, to_string(num.unwrap()));
  }
  return Ok(join(parsed_parts, "."));
}

fn compare_versions(a: String, b: String) -> Result[Int, String] {
  let a_parsed = parse_version(a);
  if !a_parsed.ok {
    return a_parsed;
  }
  let b_parsed = parse_version(b);
  if !b_parsed.ok {
    return b_parsed;
  }
  let parts_a = split(a_parsed.value, ".");
  let parts_b = split(b_parsed.value, ".");
  let mut i = 0;
  while i < len(parts_a) || i < len(parts_b) {
    let a_part = if i < len(parts_a) { parse_int(parts_a[i]) } else { Some(0) };
    let b_part = if i < len(parts_b) { parse_int(parts_b[i]) } else { Some(0) };
    if a_part.is_none() || b_part.is_none() {
      return Err("bad version".to_string());
    }
    let a_num = a_part.unwrap();
    let b_num = b_part.unwrap();
    if a_num < b_num {
      return Ok(-1);
    } else if a_num > b_num {
      return Ok(1);
    }
    i = i + 1;
  }
  return Ok(0);
}

