type Cell = (Int, Int)

fn is_land(grid: List[String], cell: Cell) -> Bool {
  let (x, y) = cell
  if x < 0 || x >= len(grid) || y < 0 || y >= str_len(grid[x]) {
    return false
  }
  return grid[x][y] == '#'
}

fn dfs(grid: List[String], cell: Cell, visited: Map[Cell, Bool]) -> Int {
  if !is_land(grid, cell) || map_get(visited, cell) == Some(true) {
    return 0
  }
  map_set(visited, cell, true)
  let (x, y) = cell
  let mut size = 1
  size = size + dfs(grid, (x - 1, y), visited)
  size = size + dfs(grid, (x + 1, y), visited)
  size = size + dfs(grid, (x, y - 1), visited)
  size = size + dfs(grid, (x, y + 1), visited)
  return size
}

fn count_islands(grid: List[String]) -> (Int, Int) {
  let mut visited = map_from([])
  let mut island_count = 0
  let mut max_size = 0
  for (i, row) in enumerate(grid) {
    for (j, _) in enumerate(row) {
      let cell = (i, j)
      if is_land(grid, cell) && map_get(visited, cell) == Some(false) {
        island_count = island_count + 1
        let size = dfs(grid, cell, visited)
        if size > max_size {
          max_size = size
        }
      }
    }
  }
  return (island_count, max_size)
}

