type Key =
  | Digit(d: Int)
  | Enter
  | Clear

type State =
  | Locked { buffer: String, failures: Int }
  | Open
  | Blocked

fn door_lock(code: String, events: List[Key]) -> String {
  let mut state = Locked { buffer: "", failures: 0 };
  for event in events {
    state = match state {
      Locked { buffer, failures } => match event {
        Digit(d) => {
          let mut new_buffer = buffer + to_string(d);
          if str_len(new_buffer) > str_len(code) {
            new_buffer = substring(new_buffer, 1, str_len(new_buffer));
          }
          Locked { buffer: new_buffer, failures }
        },
        Clear => Locked { buffer: "", failures },
        Enter => {
          if new_buffer == code {
            Locked { buffer: "", failures: 0 }
          } else {
            let new_failures = failures + 1;
            if new_failures >= 3 {
              Blocked
            } else {
              Locked { buffer: "", failures: new_failures }
            }
          }
        },
      },
      Open => Locked { buffer: "", failures: 0 },
      Blocked => Blocked,
    };
  }
  match state {
    Locked { .. } => "locked",
    Open => "open",
    Blocked => "blocked",
  }
}

