fn edit_script_distance(a: String, b: String) -> Int {
  let m = str_len(a);
  let n = str_len(b);
  let mut dp = vec![vec![0; n + 1]; m + 1];
  for i in 0..=m {
    dp[i][0] = i;
  }
  for j in 0..=n {
    dp[0][j] = j;
  }
  for i in 1..=m {
    for j in 1..=n {
      let cost = if a[i - 1] == b[j - 1] { 0 } else { 1 };
      dp[i][j] = min(
        dp[i - 1][j] + 1,  // delete
        dp[i][j - 1] + 1,  // insert
        dp[i - 1][j - 1] + cost,  // replace
      );
      if i > 1 && j > 1 && a[i - 1] == b[j - 2] && a[i - 2] == b[j - 1] {
        dp[i][j] = min(dp[i][j], dp[i - 2][j - 2] + 1);  // swap
      }
    }
  }
  return dp[m][n];
}

