fn elevator_scan(start: Int, requests: List[Int], direction: String) -> List[Int] {
  let mut served = Vec::new();
  let mut unique_requests: Map[Int, Unit] = map_from([]);

  for &req in requests {
    if req != start {
      map_set(unique_requests, req, None);
    }
  }

  let mut above = Vec::new();
  let mut below = Vec::new();

  for &req in requests {
    if req > start {
      above.push(req);
    } else if req < start {
      below.push(req);
    }
  }

  if direction == "up" {
    above.sort();
    below.sort_by(|a, b| b.cmp(a));
  } else {
    above.sort_by(|a, b| b.cmp(a));
    below.sort();
  }

  if direction == "up" || requests.contains(&start) {
    served.push(start);
  }

  for &req in above {
    served.push(req);
  }

  for &req in below {
    served.push(req);
  }

  return served;
}

