fn flatten_nested(s: String) -> Result[(List[Int], Int), String] {
  let s = s.replace(" ", "");
  let mut chars = s.chars().peekable();
  let (result, depth) = parse_list(&mut chars, 0)?;
  if chars.next().is_some() {
    return Err("invalid".to_string());
  }
  Ok((result, depth))
}

fn parse_list(chars: &mut std::iter::Peekable<std::str::Chars>, current_depth: Int) -> Result[(List[Int], Int), String] {
  if chars.next() != Some('[') {
    return Err("invalid".to_string());
  }
  let mut result = List::new();
  let mut max_depth = current_depth;
  while let Some(&c) = chars.peek() {
    if c == ']' {
      break;
    }
    if c == ',' {
      chars.next();
      continue;
    }
    let (value, new_depth) = parse_value(chars, current_depth + 1)?;
    result.push(value);
    max_depth = max_depth.max(new_depth);
  }
  if chars.next() != Some(']') {
    return Err("invalid".to_string());
  }
  Ok((result, max_depth))
}

fn parse_value(chars: &mut std::iter::Peekable<std::str::Chars>, current_depth: Int) -> Result[(Int, Int), String] {
  let mut negative = false;
  if let Some(&c) = chars.peek() {
    if c == '-' {
      negative = true;
      chars.next();
    }
  }
  let mut value = 0;
  while let Some(&c) = chars.peek() {
    if c.is_digit(10) {
      value = value * 10 + c.to_digit(10).unwrap() as Int;
      chars.next();
    } else if c == '[' {
      let (list_value, list_depth) = parse_list(chars, current_depth)?;
      value = list_value;
      max_depth = max_depth.max(list_depth);
    } else {
      break;
    }
  }
  if negative {
    value = -value;
  }
  Ok((value, current_depth))
}

