fn glob_match(pattern: String, s: String) -> Bool {
  fn match_segment(pattern: String, s: String) -> Bool {
    let mut i = 0;
    for c in pattern.chars() {
      if c == '*' {
        return s[i..].contains(&s[i..].chars().take_while(|_| true).collect::<String>());
      } else if c == '?' {
        if i >= s.len() {
          return false;
        }
        i += 1;
      } else if c == '\\' {
        if i >= s.len() || s[i] != pattern[i + 1] {
          return false;
        }
        i += 2;
      } else if i >= s.len() || s[i] != c {
        return false;
      } else {
        i += 1;
      }
    }
    i == s.len()
  }

  match_segment(pattern, s)
}

