type Meeting {
  start: Int,
  end: Int,
}

fn free_slots(meetings: List[Meeting], day_start: Int, day_end: Int) -> List[(Int, Int)]
  effects: io
  requires: day_end > day_start
{
  let mut sorted_meetings = meetings
    |> sort_by(|m| m.start)
    |> filter(|m| m.end > m.start);

  let mut free_slots = List[(Int, Int)]();

  if sorted_meetings.is_empty() {
    free_slots = append(free_slots, (day_start, day_end));
  } else {
    if sorted_meetings[0].start > day_start {
      free_slots = append(free_slots, (day_start, sorted_meetings[0].start));
    }

    for i in 1..sorted_meetings.len() {
      if sorted_meetings[i].start > sorted_meetings[i - 1].end {
        free_slots = append(free_slots, (sorted_meetings[i - 1].end, sorted_meetings[i].start));
      }
    }

    if sorted_meetings[sorted_meetings.len() - 1].end < day_end {
      free_slots = append(free_slots, (sorted_meetings[sorted_meetings.len() - 1].end, day_end));
    }
  }

  return free_slots;
}

