type Heading = { level: Int, title: String }

fn heading_numbers(lines: List[String]) -> List[String] {
  var counters = [0, 0, 0]
  var result = []: List[String]

  for line in lines {
    match parse_heading(line) {
      Some(heading) => {
        update_counters(counters, heading.level)
        result = append(result, format_heading(counters, heading.title))
      },
      None => (),
    }
  }

  return result
}

fn parse_heading(line: String) -> Option[Heading] {
  if str_len(line) < 4 && line[0] == '#' && line[1] == ' ' {
    let level = str_len(line) - 2
    let title = line[2..]
    return Some({ level: level, title: title })
  }
  return None
}

fn update_counters(counters: List[Int], level: Int) {
  for i in range(0, level) {
    counters[i] = 0
  }
  counters[level - 1] = counters[level - 1] + 1
}

fn format_heading(counters: List[Int], title: String) -> String {
  let parts = []
  for i in range(0, 3) {
    if i < counters.len() {
      parts = append(parts, to_string(counters[i]))
    }
  }
  return join(parts, ".") + " " + title
}

