type Stock {
  sku: String,
  qty: Int,
}

type Txn {
  sku: String,
  delta: Int,
}

fn inventory_ledger(stock: List[Stock], txns: List[Txn]) -> Result[List[Stock], String] {
  let mut ledger = stock;
  for (i, txn) in enumerate(txns) {
    let mut found = false;
    for s in ledger {
      if s.sku == txn.sku {
        let new_qty = s.qty + txn.delta;
        if new_qty < 0 {
          return Err(format!("txn {}: {} would go negative", i + 1, txn.sku));
        }
        s.qty = new_qty;
        found = true;
        break;
      }
    }
    if !found {
