type Request {
  endpoint: String,
  ms: Int,
  status: Int,
}

fn latency_report(entries: List[Request]) -> List[(String, Int, Int, Int)] {
  let grouped = group_by(entries, |r| r.endpoint);
  let mut result = List[None];
  for (endpoint, requests) in grouped {
    let count = len(requests);
    let errors = len(filter(requests, |r| r.status >= 500));
    let sorted_ms = sort_by(requests, |r| r.ms);
    let p90_index = (9 * count + 9) / 10;
    let p90 = if p90_index <= count { sorted_ms[p90_index - 1].ms } else { 0 };
    result = append(result, Some((endpoint, count, p90, errors)));
  }
  return filter(result, |r| r != None).map(|r| r.unwrap());
}

