type Match {
  home: String,
  away: String,
  home_goals: Int,
  away_goals: Int,
}

fn league_table(matches: List[Match]) -> List[(String, Int, Int, Int)] {
  let mut table = Map[String, (Int, Int, Int)]()

  for m in matches {
    let (home, away) = (m.home, m.away)
    let (home_goals, away_goals) = (m.home_goals, m.away_goals)

    let (mut home_points, mut home_goals_for, mut home_goals_against) = table.get_or_insert(home, (0, 0, 0))
    let (mut away_points, mut away_goals_for, mut away_goals_against) = table.get_or_insert(away, (0, 0, 0))

    if home_goals > away_goals {
      home_points += 3
    } else if home_goals == away_goals {
      home_points += 1
      away_points += 1
    }

    home_goals_for += home_goals
    home_goals_against += away_goals
    away_goals_for += away_goals
    away_goals_against += home_goals

    table.set(home, (home_points, home_goals_for, home_goals_against))
    table.set(away, (away_points, away_goals_for, away_goals_against))
  }

  let mut result = table
    |> map(|(team, (points, goals_for, goals_against))| (team, points, goals_for - goals_against, goals_for))
    |> sort_by(|(team1, _, _, _), (team2, _, _, _)| {
      if team1 == team2 {
        0
      } else if team1 > team2 {
        -1
      } else {
        1
      }
    })
    |> sort_by(|(_, points1, goals_diff1, goals_for1), (_, points2, goals_diff2, goals_for2)| {
      if points1 != points2 {
        points2 - points1
      } else if goals_diff1 != goals_diff2 {
        goals_diff2 - goals_diff1
      } else if goals_for1 != goals_for2 {
        goals_for2 - goals_for1
      } else {
        if team1 > team2 {
          -1
        } else {
          1
        }
      }
    })

  return result
}

