fn max_subarray(xs: List[Int]) -> Option[(Int, Int, Int)] {
  if xs == [] {
    return None
  }

  let mut max_sum = xs[0]
  let mut current_sum = xs[0]
  let mut start = 0
  let mut end = 0
  let mut temp_start = 0

  for (i, &x) in enumerate(xs) {
    if current_sum < 0 {
      current_sum = x
      temp_start = i
    } else {
      current_sum = current_sum + x
    }

    if current_sum > max_sum {
      max_sum = current_sum
      start = temp_start
      end = i
    }
  }

  return Some((max_sum, start, end))
}

