type OrderEvent =
  | Create(id: String)
  | Pay(id: String)
  | Ship(id: String)
  | Cancel(id: String)

fn order_states(events: List[OrderEvent]) -> Result[List[(String, String)], String] {
  var orders = map_from([])

  for event in events {
    match event {
      | Create(id) => {
        if map_get(orders, id) != None {
          return Err("duplicate order: " + id)
        }
        map_set(orders, id, "created")
      }
      | Pay(id) => {
        match map_get(orders, id) {
          | Some("created") => map_set(orders, id, "paid")
          | Some("paid") => ()
          | None => return Err("unknown order: " + id)
        }
      }
      | Ship(id) => {
        match map_get(orders, id) {
          | Some("paid") => map_set(orders, id, "shipped")
          | None => return Err("unknown order: " + id)
        }
      }
      | Cancel(id) => {
        match map_get(orders, id) {
          | Some("created") => map_set(orders, id, "cancelled")
          | Some("paid") => map_set(orders, id, "cancelled")
