fn parse_csv_line(s: String) -> Result[List[String], String] {
  let mut fields = List[String]{};
  let mut chars = s.chars().enumerate();
  let mut in_quote = false;
  let mut field = String{};

  while let Some((i, c)) = chars.next() {
    if c == '"' {
      if in_quote {
        if let Some((j, next_c)) = chars.next() {
          if next_c == '"' {
            field.push('"');
          } else {
            chars = chars.take(i + 2).chain(chars.skip(1));
            return Err(format!("unexpected quote at {}", i));
          }
        } else {
          return Err("unterminated quote".to_string());
        }
      } else {
        in_quote = true;
      }
    } else if c == ',' {
      if in_quote {
        field.push(c);
      } else {
        fields.push(field);
        field = String{};
      }
    } else {
      field.push(c);
    }
  }

  if in_quote {
    return Err("unterminated quote".to_string());
  }

  fields.push(field);
  Ok(fields)
}

