type Setting {
  section: String,
  key: String,
  value: String,
}

fn parse_config(lines: List[String]) -> Result[List[Setting], String] {
  var settings = List[Setting]()
  var current_section = ""
  var line_number = 0

  for line in lines {
    line_number = line_number + 1
    let trimmed_line = trim(line)
    if str_len(trimmed_line) == 0 || starts_with(trimmed_line, "#") {
      continue
    }

    if starts_with(trimmed_line, "[") && ends_with(trimmed_line, "]") {
      let section_name = trim(substring(trimmed_line, 1, str_len(trimmed_line) - 1))
      if str_len(section_name) == 0 {
        return Err(format("line {}: bad header", line_number))
      }
      current_section = section_name
      continue
    }

    let equals_index = find(trimmed_line, "=")
    if equals_index == -1 {
      return Err(format("line {}: missing =", line_number))
    }

    let key = trim(substring(trimmed_line, 0, equals_index))
    if str_len(key) == 0 {
      return Err(format("line {}: empty key", line_number))
    }

    let value = trim(substring(trimmed_line, equals_index + 1, str_len(trimmed_line)))
    settings = append(settings, Setting { section: current_section, key: key, value: value })
  }

  return Ok(settings)
}

