fn parse_ipv4(s: String) -> Result[Int, String] {
  let parts = s.split(".").collect::<Vec<&str>>();
  if parts.len() != 4 {
    return Err("expected 4 parts".to_string());
  }
  let mut value = 0;
  for (i, part) in parts.iter().enumerate() {
    let num = match part.parse::<Int>() {
      Ok(n) if n >= 0 && n <= 255 => n,
      _ => return Err(format!("bad part: {}", part)),
    };
    if part.len() > 1 && part.starts_with('0') {
      return Err(format!("bad part: {}", part));
    }
    value += num * match i {
      0 => 16777216,
      1 => 65536,
      2 => 256,
      3 => 1,
      _ => unreachable!(),
    };
  }
  Ok(value)
}

