fn parse_duration(s: String) -> Result[Int, String] {
  if str_len(s) == 0 {
    return Err("empty".to_string());
  }

  let mut seconds = 0;
  let mut h_found = false;
  let mut m_found = false;
  let mut s_found = false;

  let mut i = 0;
  while i < str_len(s) {
    let mut num = 0;
    while i < str_len(s) && s[i] >= '0' && s[i] <= '9' {
      num = num * 10 + (s[i] as u8 - b'0') as Int;
      i += 1;
    }

    if i == str_len(s) {
      return Err("missing unit".to_string());
    }

    let unit = s[i];
    i += 1;

    match unit {
      'h' => {
        if h_found || m_found || s_found {
          return Err("unit out of order: h".to_string());
        }
        seconds += num * 3600;
        h_found = true;
      },
      'm' => {
        if m_found || s_found {
          return Err("unit out of order: m".to_string());
        }
        seconds += num * 60;
        m_found = true;
      },
      's' => {
        if s_found {
          return Err("unit out of order: s".to_string());
        }
        seconds += num;
        s_found = true;
      },
      _ => {
        return Err(format!("unknown unit: {}", unit));
      },
    }
  }

  Ok(seconds)
}

