fn parse_money(s: String) -> Result[Int, String] {
  let s = s.trim();
  if s.starts_with('-') {
    s = &s[1..];
  }
  if !s.starts_with('$') {
    return Err("missing $".to_string());
  }
  s = &s[1..];
  let parts: Vec<&str> = s.split('.').collect();
  if parts.len() != 2 {
    return Err("bad cents".to_string());
  }
  let dollars = parts[0];
  let cents = parts[1];
  if cents.len() != 2 {
    return Err("bad cents".to_string());
  }
  if dollars.starts_with('0') && dollars.len() > 1 {
    return Err("bad dollars".to_string());
  }
  let dollars_int = parse_int(dollars).ok_or("bad dollars".to_string())?;
  let cents_int = parse_int(cents).ok_or("bad cents".to_string())?;
  Ok(dollars_int * 100 + cents_int)
}

