fn parse_query(s: String) -> Result[List[(String, String)], String] {
  let items = s.split("&").filter(|i| !i.is_empty()).map(|i| i.split_once("=").unwrap_or((i, ""))).map(|(k, v)| (k.replace("+", " "), v.replace("+", " "))).collect::<List[(String, String)]>();
  for (k, _) in &items {
    if k.is_empty() {
      return Err(format!("empty key: {}", s));
    }
  }
  return Ok(items);
}

