fn pig_latin(s: String) -> String {
  let words = split(s, " ")
  let translated = map(words, |w| translate_word(w))
  return join(translated, " ")
}

fn translate_word(w: String) -> String {
  let vowels = "aeiou"
  let mut chars = w.chars().collect::<Vec<char>>()
  let mut first_vowel_index = None

  for (i, c) in chars.iter().enumerate() {
    if *c == 'y' && i == 0 {
      continue
    }
    if vowels.contains(c) {
      first_vowel_index = Some(i)
      break
    }
  }

  match first_vowel_index {
    Some(i) if i == 0 => return w + "way",
    Some(i) => {
      let prefix = chars.drain(0..i).collect::<String>()
      return chars.join("") + &prefix + "ay"
    },
    None => return w + "ay",
  }
}

