fn rle_compress(s: String) -> String {
  let chars = s.chars().collect::<Vec<_>>();
  let mut compressed = String::new();
  let mut i = 0;

  while i < chars.len() {
    let c = chars[i];
    let mut count = 0;
    while i < chars.len() && chars[i] == c {
      count += 1;
      i += 1;
    }
    compressed.push(c);
    if count > 1 {
      compressed.push_str(&count.to_string());
    }
  }

  if compressed.len() >= s.len() {
    return s;
  } else {
    return compressed;
  }
}

