type Cmd =
  | Forward(steps: Int)
  | TurnLeft
  | TurnRight

fn robot_walk(cmds: List[Cmd], obstacles: List[(Int, Int)]) -> (Int, Int, String) {
  let mut x = 0
  let mut y = 0
  let mut direction = "N"

  for cmd in cmds {
    match cmd {
      Forward(steps) => {
        for _ in 0..steps {
          let (new_x, new_y) = match direction {
            "N" => (x, y + 1),
            "E" => (x + 1, y),
            "S" => (x, y - 1),
            "W" => (x - 1, y),
            _ => (x, y),
          };
          if !obstacles.contains(&(new_x, new_y)) {
            x = new_x
            y = new_y
          } else {
            break
          }
        }
      },
      TurnLeft => {
        direction = match direction {
          "N" => "W",
          "E" => "N",
          "S" => "E",
          "W" => "S",
          _ => direction,
        }
      },
      TurnRight => {
        direction = match direction {
          "N" => "E",
          "E" => "S",
          "S" => "W",
          "W" => "N",
          _ => direction,
        }
      },
    }
  }

  return (x, y, direction)
}

