type Session {
  user: String,
  kind: String,
  time: Int,
}

fn session_totals(events: List[Session]) -> List[(String, Int)] {
  let mut sessions = Map[String, (Int, Int)]()
  let mut last_time = 0
  for e in events {
    if e.kind == "login" {
      if !sessions.contains_key(e.user) {
        sessions.set(e.user, (e.time, e.time))
      }
    } else if e.kind == "logout" {
      if sessions.contains_key(e.user) {
        let (start, _) = sessions.get(e.user)
        sessions.set(e.user, (*start, e.time))
      }
    }
    last_time = e.time
  }
  for (user, (start, end)) in sessions {
    sessions.set(user, (start, last_time))
  }
  let mut result = List[(String, Int)]()
  for (user, (start, end)) in sessions {
    result.append((user, end - start))
  }
  result.sort_by(|a, b| a.0 < b.0)
  return result
}

