type Expense {
  payer: String,
  amount_cents: Int,
}

fn total_expenses(expenses: List[Expense]) -> Int {
  return expenses |> map(|e| e.amount_cents) |> sum();
}

fn settle_debts(expenses: List[Expense], people: List[String]) -> List[(String, String, Int)] {
  let total = total_expenses(expenses);
  let per_person = total / len(people);
  let remainder = total % len(people);
  let mut balances = map_from(people |> map(|p| (p, per_person)));
  people |> enumerate() |> for_each(|(i, p)| map_set(balances, p, map_get(balances, p) + (i < remainder)));
  let mut payments = [];
  while true {
    let debtor = people |> filter(|p| map_get(balances, p) < 0) |> sort_by(|p| map_get(balances, p)) |> first();
    let creditor = people |> filter(|p| map_get(balances, p) > 0) |> sort_by(|p| map_get(balances, p)) |> first();
    if debtor == null || creditor == null {
      break;
    }
    let amount = min(-map_get(balances, debtor), map_get(balances, creditor));
    map_set(balances, debtor, map_get(balances, debtor) + amount);
    map_set(balances, creditor, map_get(balances, creditor) - amount);
    payments = append(payments, (debtor, creditor, amount));
  }
  return payments;
}

