type RomanNumeral {
  kind: String,
  value: Int,
}

fn roman_to_int(s: String) -> Result[Int, String] {
  if str_len(s) == 0 {
    return Err("empty".to_string());
  }

  let roman_map: Map[String, RomanNumeral] = map_from([
    ("M", RomanNumeral { kind: "M", value: 1000 }),
    ("CM", RomanNumeral { kind: "CM", value: 900 }),
    ("D", RomanNumeral { kind: "D", value: 500 }),
    ("CD", RomanNumeral { kind: "CD", value: 400 }),
    ("C", RomanNumeral { kind: "C", value: 100 }),
    ("XC", RomanNumeral { kind: "XC", value: 90 }),
    ("L", RomanNumeral { kind: "L", value: 50 }),
    ("XL", RomanNumeral { kind: "XL", value: 40 }),
    ("X", RomanNumeral { kind: "X", value: 10 }),
    ("IX", RomanNumeral { kind: "IX", value: 9 }),
    ("V", RomanNumeral { kind: "V", value: 5 }),
    ("IV", RomanNumeral { kind: "IV", value: 4 }),
    ("I", RomanNumeral { kind: "I", value: 1 }),
  ]);

  let mut result = 0;
  let mut i = 0;

  while i < str_len(s) {
    if i + 1 < str_len(s) && map_get(roman_map, s[i..i+2]) != None {
      let numeral = map_get(roman_map, s[i..i+2]).unwrap();
      result = result + numeral.value;
      i = i + 2;
    } else {
      let numeral = map_get(roman_map, s[i..i+1]).unwrap();
      result = result + numeral.value;
      i = i + 1;
    }
  }

  if result < 1 || result > 3999 {
    return Err("not canonical".to_string());
  }

  return Ok(result);
}

