fn spiral_order(m: List[List[Int]]) -> List[Int] {
  let rows = len(m);
  let cols = if rows > 0 { len(m[0]) } else { 0 };
  let mut result = [];
  let mut top = 0;
  let mut bottom = rows - 1;
  let mut left = 0;
  let mut right = cols - 1;

  while top <= bottom && left <= right {
    for i in range(left, right + 1) {
      append(result, m[top][i]);
    }
    top = top + 1;

    for i in range(top, bottom + 1) {
      append(result, m[i][right]);
    }
    right = right - 1;

    if top <= bottom {
      for i in range(right, left - 1, -1) {
        append(result, m[bottom][i]);
      }
      bottom = bottom - 1;
    }

    if left <= right {
      for i in range(bottom, top - 1, -1) {
        append(result, m[i][left]);
      }
      left = left + 1;
    }
  }

  return result;
}

