type Student {
  name: String,
  scores: List[Int],
}

fn median(scores: List[Int]) -> Option[Float] {
  let n = len(scores)
  if n == 0 {
    return None
  }
  let sorted = sort(scores)
  if n % 2 == 1 {
    return Some(to_float(sorted[n / 2]))
  } else {
    let mid1 = sorted[n / 2 - 1]
    let mid2 = sorted[n / 2]
    return Some((to_float(mid1) + to_float(mid2)) / 2.0)
  }
}

fn student_medians(students: List[Student]) -> List[(String, Float)] {
  students
    |> filter(|s| len(s.scores) > 0)
    |> map(|s| (s.name, median(s.scores).unwrap_or(0.0)))
    |> sort_by(|a, b| if a.1 == b.1 { a.0.cmp(&b.0) } else { b.1.cmp(&a.1) })
}

