type EditOp =
  | Insert(text: String)
  | Delete(n: Int)
  | Left(n: Int)
  | Right(n: Int)
  | Undo

fn text_editor(ops: List[EditOp]) -> String {
  var text = ""
  var cursor = 0
  var history = []

  for op in ops {
    match op {
      Insert(t) => {
        history = (text, cursor) :: history
        text = text[0, cursor] + t + text[cursor, len(text)]
        cursor = cursor + len(t)
      },
      Delete(n) => {
        history = (text, cursor) :: history
