type Instr =
  | Push(n: Int)
  | Pop
  | Add
  | Sub
  | Mul
  | Dup
  | Swap
  | Jz(target: Int)
  | Jmp(target: Int)
  | Print
  | Halt

fn stack_vm(prog: List[Instr]) -> Result[List[Int], String] {
  effects: io
  requires: len(prog) <= 1000
  ensures: result.is_ok() || result.is_err()
{
  var stack: List[Int] = []
  var ip = 0
  var steps = 0
  var output: List[Int] = []

  while ip < len(prog) && steps < 1000 {
    steps = steps + 1
    match prog[ip] {
      Push(n) => stack = append(stack, n),
      Pop => {
        if len(stack) == 0 {
          return Err("stack underflow at " + to_string(ip))
        }
        stack = drop(stack, 1)
      },
      Add => {
        if len(stack) < 2 {
          return Err("stack underflow at " + to_string(ip))
        }
        stack = append(drop(drop(stack, 1), 1), stack[0] + stack[1])
      },
      Sub => {
        if len(stack) < 2 {
          return Err("stack underflow at " + to_string(ip))
        }
        stack = append(drop(drop(stack, 1), 1), stack[0] - stack[1])
      },
      Mul => {
        if len(stack) < 2 {
          return Err("stack underflow at " + to_string(ip))
        }
        stack = append(drop(drop(stack, 1), 1), stack[0] * stack[1])
      },
      Dup => {
        if len(stack) == 0 {
          return Err("stack underflow at " + to_string(ip))
        }
        stack = append(stack, stack[0])
      },
      Swap => {
        if len(stack) < 2 {
          return Err("stack underflow at " + to_string(ip))
        }
        let a = stack[0]
        stack = append(drop(stack, 1), a)
        let b = stack[0]
        stack = append(drop(stack, 1), b)
      },
      Jz(target) => {
        if len(stack) == 0 {
          return Err("stack underflow at " + to_string(ip))
        }
        if stack[0] == 0 {
          if target < 0 || target >= len(prog) {
            return Err("bad jump at " + to_string(ip))
          }
          ip = target
        } else {
          ip = ip + 1
        }
      },
      Jmp(target) => {
        if target < 0 || target >= len(prog) {
          return Err("bad jump at " + to_string(ip))
        }
        ip = target
      },
      Print => {
        if len(stack) == 0 {
          return Err("stack underflow at " + to_string(ip))
        }
        output = append(output, stack[0])
        stack = drop(stack, 1)
      },
      Halt => return Ok(output),
    }
    ip = ip + 1
  }

  if ip >= len(prog) {
    return Ok(output)
  } else {
    return Err("step limit exceeded")
  }
}

