type Board = List[String]

fn tic_tac_toe(board: Board) -> String {
  let rows = board
  let cols = transpose(rows)
  let diags = [rows[0][0] + rows[1][1] + rows[2][2], rows[0][2] + rows[1][1] + rows[2][0]]
  let all_lines = rows ++ cols ++ diags

  let count_marks(line: String, mark: String) -> Int {
    return line.filter(|c| c == mark).len()
  }

  let count_x = all_lines.map(|line| count_marks(line, "X")).sum()
  let count_o = all_lines.map(|line| count_marks(line, "O")).sum()

  if count_x != count_o && count_x != count_o + 1 {
    return "invalid"
  }

  let has_line(line: String) -> Bool {
    return line == "XXX" || line == "OOO"
  }

  if all_lines.exists(has_line) {
    if count_x == count_o {
      return "O wins"
    } else if count_x == count_o + 1 {
      return "X wins"
    } else {
      return "invalid"
    }
  }

  if rows.exists(|row| row == "..." && cols.exists(|col| col == "...") && diags.exists(|diag| diag == "...")) {
    return "in progress"
  }

  if count_x + count_o == 9 {
    return "draw"
  }

  return "invalid"
}

fn transpose(rows: Board) -> Board {
  let n = rows[0].len()
  let mut cols = List[String]()
  for i in range(0, n) {
    let mut col = ""
    for row in rows {
      col = col + row[i]
    }
    cols = cols.append(col)
  }
  return cols
}

