type Token =
  | Num(value: Int)
  | Ident(name: String)
  | Sym(text: String)

fn tokenize(s: String) -> Result[List[Token], String] {
  let chars = s.chars().collect::<Vec<char>>();
  let mut tokens = Vec::new();
  let mut i = 0;

  while i < chars.len() {
    match chars[i] {
      ' ' => i += 1,
      '0'..='9' => {
        let mut num = 0;
        while i < chars.len() && chars[i].is_digit(10) {
          num = num * 10 + chars[i].to_digit(10).unwrap() as Int;
          i += 1;
        }
        tokens.push(Num(num));
      },
      'a'..='z' | '_' => {
        let mut name = chars[i].to_string();
        i += 1;
        while i < chars.len() && (chars[i].is_digit(10) || chars[i].is_alphabetic() || chars[i] == '_') {
          name.push(chars[i]);
          i += 1;
        }
        tokens.push(Ident(name));
      },
      '+' | '-' | '*' | '/' | '=' | '<' | '>' | '(' | ')' | ',' => {
        let sym = chars[i].to_string();
        i += 1;
        if i < chars.len() && sym == "<=" || sym == ">=" || sym == "==" || sym == "!=" {
          tokens.push(Sym(sym));
          i += 1;
        } else {
          tokens.push(Sym(sym));
        }
      },
      _ => return Err(format!("unexpected character: {} at {}", chars[i], i)),
    }
  }

  Ok(tokens)
}

