fn wrap_text(s: String, width: Int) -> List[String] {
  let words = s.trim().split_whitespace().collect::<List[String]>();
  let mut lines = List[String]();
  let mut line = String::new();

  for word in words {
    if str_len(line) + str_len(word) + 1 <= width {
      if !line.is_empty() {
        line = line + " " + word;
      } else {
        line = word;
      }
    } else {
      lines = lines.append(line);
      line = word;
    }
  }

  if !line.is_empty() {
    lines = lines.append(line);
  }

  return lines;
}

