from typing import Generic, Literal, TypedDict, TypeVar

T = TypeVar("T")

class Ok(TypedDict, Generic[T]):
    ok: Literal[True]
    value: T

class Err(TypedDict):
    ok: Literal[False]
    error: str

class Job(TypedDict):
    name: str
    deps: list[str]

def build_order(jobs: list[Job]) -> Ok[list[str]] | Err:
    job_names = {job['name'] for job in jobs}
    if len(job_names) != len(jobs):
        first_duplicate = next(name for name in jobs if jobs.count(name) > 1)
        return Err({"ok": False, "error": f"duplicate job: {first_duplicate}"})

    job_map = {job['name']: job for job in jobs}
    dependency_map = {job['name']: set(job['deps']) for job in jobs}
    remaining_jobs = job_names.copy()
    ordered_jobs = []

    while remaining_jobs:
        available_jobs = [job for job in remaining_jobs if not dependency_map[job]]
        if not available_jobs:
            return Err({"ok": False, "error": "cycle detected"})
        next_job = available_jobs[0]
        ordered_jobs.append(next_job)
        remaining_jobs.remove(next_job)
        for dependent in job_map[next_job]['deps']:
            dependency_map[dependent].remove(next_job)

    return Ok({"ok": True, "value": ordered_jobs})

