def parse_version(version: str) -> Ok[list[int]] | Err:
    parts = version.split('.')
    parsed_parts = []
    for part in parts:
        if not part.isdigit():
            return Err(ok=False, error=f"bad version: {version}")
        parsed_parts.append(int(part))
    return Ok(ok=True, value=parsed_parts)

def compare_versions(a: str, b: str) -> Ok[int] | Err:
    result_a = parse_version(a)
    if not result_a['ok']:
        return result_a
    result_b = parse_version(b)
    if not result_b['ok']:
        return result_b

    version_a = result_a['value']
    version_b = result_b['value']

    max_length = max(len(version_a), len(version_b))
    version_a += [0] * (max_length - len(version_a))
    version_b += [0] * (max_length - len(version_b))

    for i in range(max_length):
        if version_a[i] < version_b[i]:
            return Ok(ok=True, value=-1)
        elif version_a[i] > version_b[i]:
            return Ok(ok=True, value=1)

    return Ok(ok=True, value=0)

