def count_islands(grid: list[str]) -> tuple[int, int]:
    if not grid or not grid[0]:
        return 0, 0

    rows, cols = len(grid), len(grid[0])
    visited = [[False] * cols for _ in range(rows)]
    max_island_size = 0
    island_count = 0

    def dfs(r: int, c: int) -> int:
        if r < 0 or r >= rows or c < 0 or c >= cols or grid[r][c] == '.' or visited[r][c]:
            return 0
        visited[r][c] = True
        size = 1
        for dr, dc in [(-1, 0), (1, 0), (0, -1), (0, 1)]:
            size += dfs(r + dr, c + dc)
        return size

    for r in range(rows):
        for c in range(cols):
            if grid[r][c] == '#' and not visited[r][c]:
                island_count += 1
                max_island_size = max(max_island_size, dfs(r, c))

    return island_count, max_island_size

