def door_lock(code: str, events: list[Key]) -> str:
    buffer = []
    failure_count = 0
    state = "locked"

    for event in events:
        if state == "locked":
            if event["kind"] == "Digit":
                buffer.append(event["d"])
                if len(buffer) > len(code):
                    buffer.pop(0)
            elif event["kind"] == "Clear":
                buffer.clear()
            elif event["kind"] == "Enter":
                if ''.join(map(str, buffer)) == code:
                    state = "open"
                    failure_count = 0
                else:
                    failure_count += 1
                    if failure_count == 3:
                        state = "blocked"
                buffer.clear()
        elif state == "open":
            if event["kind"] == "Enter":
                state = "locked"
        elif state == "blocked":
            pass

    return state

from __future__ import annotations

def edit_script_distance(a: str, b: str) -> int:
    m, n = len(a), len(b)
    dp = [[0] * (n + 1) for _ in range(m + 1)]

    for i in range(m + 1):
        dp[i][0] = i
    for j in range(n + 1):
        dp[0][j] = j

    for i in range(1, m + 1):
        for j in range(1, n + 1):
            if a[i - 1] == b[j - 1]:
                dp[i][j] = dp[i - 1][j - 1]
            else:
                dp[i][j] = min(
                    dp[i - 1][j] + 1,      # Delete
                    dp[i][j - 1] + 1,      # Insert
                    dp[i - 1][j - 1] + 1,  # Replace
                )

    return dp[m][n]

