        return Err(error="invalid roll")

    score = 0
    i = 0
    for frame in range(10):
        if i >= len(rolls):
            return Err(error="incomplete game")

        if rolls[i] == 10:  # Strike
            score += 10 + sum(rolls[i+1:i+3])
            i += 1
        elif rolls[i] + rolls[i+1] > 10:
            return Err(error=f"too many pins in frame {frame + 1}")
        else:  # Open frame
            score += rolls[i] + rolls[i+1]
            i += 2

    if i < len(rolls):
        return Err(error="too many rolls")

    return Ok(value=score)

