def glob_match(pattern: str, s: str) -> bool:
    def match(i: int, j: int) -> bool:
        if i == len(pattern) and j == len(s):
            return True
        if i == len(pattern) or j == len(s):
            return False
        if pattern[i] == '*':
            return match(i + 1, j) or match(i, j + 1)
        if pattern[i] == '?':
            return match(i + 1, j + 1)
        if pattern[i] == '\\' and i + 1 < len(pattern):
            if pattern[i + 1] == s[j]:
                return match(i + 2, j + 1)
            else:
                return False
        if pattern[i] == '\\' and i + 1 == len(pattern):
            return s[j] == '\\'
        if pattern[i] == s[j]:
            return match(i + 1, j + 1)
        return False

    return match(0, 0)

