def life_step(grid: list[str], steps: int) -> list[str]:
    def count_live_neighbors(grid: list[str], row: int, col: int) -> int:
        count = 0
        rows, cols = len(grid), len(grid[0])
        for i in range(max(0, row-1), min(rows, row+2)):
            for j in range(max(0, col-1), min(cols, col+2)):
                if (i, j) != (row, col) and grid[i][j] == '#':
                    count += 1
        return count

    def next_generation(grid: list[str]) -> list[str]:
        new_grid = ['' for _ in range(len(grid))]
        for i in range(len(grid)):
            for j in range(len(grid[0])):
                live_neighbors = count_live_neighbors(grid, i, j)
                if (grid[i][j] == '#' and (live_neighbors == 2 or live_neighbors == 3)) or (grid[i][j] == '.' and live_neighbors == 3):
                    new_grid[i] += '#'
                else:
                    new_grid[i] += '.'
        return new_grid

    for _ in range(steps):
        grid = next_generation(grid)
    return grid

