def flatten_nested(s: str) -> Ok[tuple[list[int], int]] | Err:
    s = s.replace(" ", "")
    stack: list[list[int]] = []
    result: list[int] = []
    depth = 0
    max_depth = 0

    i = 0
    while i < len(s):
        if s[i] == '[':
            depth += 1
            max_depth = max(max_depth, depth)
            stack.append([])
        elif s[i] == ']':
            depth -= 1
            if not stack:
                return Err({"ok": False, "error": f"invalid at {i}"})
            sublist = stack.pop()
            if stack:
                stack[-1].extend(sublist)
            else:
                result.extend(sublist)
        elif s[i] == ',':
            if not stack:
                return Err({"ok": False, "error": f"invalid at {i}"})
        elif s[i].isdigit() or s[i] == '-':
            j = i
            while j < len(s) and (s[j].isdigit() or s[j] == '-'):
                j += 1
            num = int(s[i:j])
            if stack:
                stack[-1].append(num)
            else:
                result.append(num)
            i = j - 1
        else:
            return Err({"ok": False, "error": f"invalid at {i}"})
        i += 1

    if stack:
        return Err({"ok": False, "error": f"invalid at {i}"})

    return Ok({"ok": True, "value": (result, max_depth)})

