def lis_length(xs: list[int]) -> tuple[int, int]:
    if not xs:
        return (0, 0)

    n = len(xs)
    lengths = [1] * n
    counts = [1] * n

    for i in range(1, n):
        for j in range(i):
            if xs[i] > xs[j]:
                if lengths[j] + 1 > lengths[i]:
                    lengths[i] = lengths[j] + 1
                    counts[i] = counts[j]
                elif lengths[j] + 1 == lengths[i]:
                    counts[i] += counts[j]

    max_length = max(lengths)
    total_count = sum(count for length, count in zip(lengths, counts) if length == max_length)

    return (max_length, total_count)

