def min_coins(coins: list[int], amount: int) -> tuple[int, list[int]] | None:
    if amount < 0:
        return None
    if amount == 0:
        return 0, []

    coins.sort(reverse=True)
    result = _min_coins(coins, amount)
    if result is None:
        return None
    return result

def _min_coins(coins: list[int], amount: int) -> tuple[int, list[int]] | None:
    if amount == 0:
        return 0, []
    if not coins:
        return None

    coin = coins[0]
    if coin > amount:
        return _min_coins(coins[1:], amount)

    with_coin = _min_coins(coins, amount - coin)
    without_coin = _min_coins(coins[1:], amount)

    if with_coin is None and without_coin is None:
        return None
    if with_coin is None:
        return without_coin
    if without_coin is None:
        return with_coin

    with_count, with_used = with_coin
    without_count, without_used = without_coin

    if with_count < without_count:
        return with_count + 1, [coin] + with_used
    if with_count > without_count:
        return without_count, without_used
    if with_used > without_used:
        return with_count + 1, [coin] + with_used
    return with_count + 1, [coin] + with_used

