from __future__ import annotations

def max_subarray(xs: list[int]) -> tuple[int, int, int] | None:
    if not xs:
        return None
    max_sum = float('-inf')
    start = end = 0
    current_sum = 0
    temp_start = 0
    for i, x in enumerate(xs):
        if current_sum <= 0:
            temp_start = i
            current_sum = x
        else:
            current_sum += x
        if current_sum > max_sum:
            max_sum = current_sum
            start = temp_start
            end = i
    return int(max_sum), start, end

