def parse_duration(s: str) -> Ok[int] | Err:
    if not s:
        return Err(ok=False, error="empty")

    units = {'h': 3600, 'm': 60, 's': 1}
    result = 0
    i = 0
    while i < len(s):
        if s[i].isdigit():
            j = i
            while j < len(s) and s[j].isdigit():
                j += 1
            num = int(s[i:j])
            i = j
            if i < len(s) and s[i] in units:
                result += num * units[s[i]]
                i += 1
            else:
                return Err(ok=False, error="missing unit before " + s[i])
        elif s[i] in units:
            if i > 0 and s[i-1].isdigit():
                return Err(ok=False, error="unit out of order: " + s[i])
            else:
                return Err(ok=False, error="missing number before " + s[i])
        else:
            return Err(ok=False, error="unknown unit: " + s[i])

    if i < len(s) and s[i:].isdigit():
        return Err(ok=False, error="missing unit")

    return Ok(ok=True, value=result)

