from typing import TypedDict

class Contact(TypedDict):
    name: str
    email: str
    phone: str

def merge_contacts(contacts: list[Contact]) -> list[Contact]:
    if not contacts:
        return []

    # Create a dictionary to map email and phone to their respective contacts
    email_map: dict[str, Contact] = {}
    phone_map: dict[str, Contact] = {}

    # Populate the maps
    for contact in contacts:
        email = contact['email'].strip()
        phone = ''.join(filter(str.isdigit, contact['phone']))
        if email:
            email_map[email] = contact
        if phone:
            phone_map[phone] = contact

    # Find connected components
    visited = set()
    components: list[list[Contact]] = []

    def dfs(contact: Contact) -> None:
        stack = [contact]
        while stack:
            current = stack.pop()
            if current not in visited:
                visited.add(current)
                components[-1].append(current)
                for email in email_map:
                    if email_map[email]['email'].strip() == current['email'].strip():
                        stack.append(email_map[email])
                for phone in phone_map:
                    if phone_map[phone]['phone'] == current['phone']:
                        stack.append(phone_map[phone])

    for contact in contacts:
        if contact not in visited:
            components.append([])
            dfs(contact)

    # Merge contacts in each component
    merged_contacts = []
    for component in components:
        merged = component[0].copy()
        for contact in component[1:]:
            for field in merged:
                if merged[field] == "":
                    merged[field] = contact[field]
        merged_contacts.append(merged)

    return merged_contacts

