class Forward(TypedDict):
    kind: Literal["Forward"]
    steps: int

class TurnLeft(TypedDict):
    kind: Literal["TurnLeft"]

class TurnRight(TypedDict):
    kind: Literal["TurnRight"]

Cmd = Forward | TurnLeft | TurnRight

def robot_walk(cmds: list[Cmd], obstacles: list[tuple[int, int]]) -> tuple[int, int, str]:
    x, y = 0, 0
    direction = "N"
    for cmd in cmds:
        if cmd["kind"] == "TurnLeft":
            if direction == "N":
                direction = "W"
            elif direction == "W":
                direction = "S"
            elif direction == "S":
                direction = "E"
            elif direction == "E":
                direction = "N"
        elif cmd["kind"] == "TurnRight":
            if direction == "N":
                direction = "E"
            elif direction == "E":
                direction = "S"
            elif direction == "S":
                direction = "W"
            elif direction == "W":
                direction = "N"
        elif cmd["kind"] == "Forward":
            for _ in range(cmd["steps"]):
                if direction == "N" and (x, y + 1) not in obstacles:
                    y += 1
                elif direction == "E" and (x + 1, y) not in obstacles:
                    x += 1
                elif direction == "S" and (x, y - 1) not in obstacles:
                    y -= 1
                elif direction == "W" and (x - 1, y) not in obstacles:
                    x -= 1
                else:
                    break
    return (x, y, direction)

