def roman_to_int(s: str) -> Ok[int] | Err:
    if not s:
        return Err(ok=False, error="empty")

    roman_map = {
        'I': 1, 'V': 5, 'X': 10, 'L': 50, 'C': 100, 'D': 500, 'M': 1000
    }
    subtractive_pairs = {'IV': 4, 'IX': 9, 'XL': 40, 'XC': 90, 'CD': 400, 'CM': 900}

    value = 0
    i = 0
    while i < len(s):
        if s[i:i+2] in subtractive_pairs:
            value += subtractive_pairs[s[i:i+2]]
            i += 2
        elif s[i] in roman_map:
            value += roman_map[s[i]]
            i += 1
        else:
            return Err(ok=False, error=f"invalid character: {s[i]}")

    if not (1 <= value <= 3999):
        return Err(ok=False, error="not canonical")

    return Ok(ok=True, value=value)

