def session_totals(events: list[Session]) -> list[tuple[str, int]]:
    user_sessions: dict[str, list[int]] = {}
    for event in events:
        if event['kind'] == 'login':
            if event['user'] not in user_sessions:
                user_sessions[event['user']] = [event['time']]
        elif event['kind'] == 'logout':
            if event['user'] in user_sessions and len(user_sessions[event['user']]) > 0:
                user_sessions[event['user']].append(event['time'])
    for user in user_sessions:
        user_sessions[user] = [user_sessions[user][i] - user_sessions[user][i-1] for i in range(1, len(user_sessions[user]))]
    return sorted((user, sum(times)) for user, times in user_sessions.items())

