def pig_latin(s: str) -> str:
    words = s.split()
    translated_words = []
    for word in words:
        if not word:
            translated_words.append("")
            continue
        vowels = "aeiou"
        if word[0] in vowels or (word[0] == 'y' and len(word) > 1 and word[1] in vowels):
            translated_words.append(word + "way")
        else:
            for i, char in enumerate(word):
                if char in vowels or (char == 'y' and i > 0 and word[i-1] != 'q'):
                    translated_words.append(word[i:] + word[:i] + "ay")
                    break
    return " ".join(translated_words)

