T = TypeVar("T")

class Ok(TypedDict, Generic[T]):
    ok: Literal[True]
    value: T

class Err(TypedDict):
    ok: Literal[False]
    error: str

def sliding_window_max(xs: list[int], k: int) -> Ok[list[int]] | Err:
    if k < 1:
        return Err({"ok": False, "error": "window must be positive"})
    if k > len(xs):
        return Err({"ok": False, "error": "window larger than input"})

    result = []
    for i in range(len(xs) - k + 1):
        result.append(max(xs[i:i+k]))

    return Ok({"ok": True, "value": result})

from __future__ import annotations

def spiral_order(m: list[list[int]]) -> list[int]:
    if not m or not m[0]:
        return []

    result = []
    while m:
        # Top row
        result += m.pop(0)
        # Right column
        if m and m[0]:
            for row in m:
                result.append(row.pop())
        # Bottom row
        if m:
            result += m.pop()[::-1]
        # Left column
        if m and m[0]:
            for row in m[::-1]:
                result.append(row.pop(0))
    return result

