class Insert(TypedDict):
    kind: Literal["Insert"]
    text: str

class Delete(TypedDict):
    kind: Literal["Delete"]
    n: int

class Left(TypedDict):
    kind: Literal["Left"]
    n: int

class Right(TypedDict):
    kind: Literal["Right"]
    n: int

class Undo(TypedDict):
    kind: Literal["Undo"]

EditOp = Insert | Delete | Left | Right | Undo

def text_editor(ops: list[EditOp]) -> str:
    text = ""
    cursor = 0
    history: list[tuple[str, int]] = []

    for op in ops:
        if op["kind"] == "Insert":
            history.append((text, cursor))
            text = text[:cursor] + op["text"] + text[cursor:]
            cursor += len(op["text"])
        elif op["kind"] == "Delete":
            history.append((text, cursor))
            n = min(op["n"], cursor)
            text = text[:cursor - n] + text[cursor:]
            cursor -= n
        elif op["kind"] == "Left":
            history.append((text, cursor))
            cursor = max(0, cursor - op["n"])
        elif op["kind"] == "Right":
            history.append((text, cursor))
            cursor = min(len(text), cursor + op["n"])
        elif op["kind"] == "Undo":
            if history:
                text, cursor = history.pop()

    return text

from __future__ import annotations

def tic_tac_toe(board: list[str]) -> str:
    def check_line(line: str) -> bool:
        return line == "XXX" or line == "OOO"

    def check_winner(board: list[str]) -> str:
        # Check rows
        for row in board:
            if check_line(row):
                return "X wins" if row == "XXX" else "O wins"
        # Check columns
        for col in range(3):
            if check_line("".join(board[row][col] for row in range(3))):
                return "X wins" if board[0][col] == "X" else "O wins"
        # Check diagonals
        if check_line("".join(board[i][i] for i in range(3))):
            return "X wins" if board[0][0] == "X" else "O wins"
        if check_line("".join(board[i][2 - i] for i in range(3))):
            return "X wins" if board[0][2] == "X" else "O wins"
        return "draw" if all(cell != "." for row in board for cell in row) else "in progress"

    x_count = sum(row.count("X") for row in board)
    o_count = sum(row.count("O") for row in board)

    if abs(x_count - o_count) > 1:
        return "invalid"
    if x_count < o_count:
        return "invalid"
    if x_count == o_count and check_winner(board) == "X wins":
        return "invalid"
    if x_count == o_count + 1 and check_winner(board) == "O wins":
        return "invalid"

    return check_winner(board)

from __future__ import annotations

def tennis_score(points: str) -> str:
    score = {"A": 0, "B": 0}
    for point in points:
        if point not in score:
            return "error: bad point"
        score[point] += 1
        if score[point] >= 4 and score[point] - score[point if point == "A" else "B"] >= 2:
            return f"game {point}"
        if score["A"] >= 3 and score["B"] >= 3:
            if score["A"] == score["B"]:
                return "deuce"
            return f"advantage {point}"
    return f"{score['A']}-all" if score["A"] == score["B"] else f"{score['A']}-{score['B']}"

