T = TypeVar("T")

class Ok(TypedDict, Generic[T]):
    ok: Literal[True]
    value: T

class Err(TypedDict):
    ok: Literal[False]
    error: str

class Num(TypedDict):
    kind: Literal["Num"]
    value: int

class Ident(TypedDict):
    kind: Literal["Ident"]
    name: str

class Sym(TypedDict):
    kind: Literal["Sym"]
    text: str

Token = Num | Ident | Sym

def tokenize(s: str) -> Ok[list[Token]] | Err:
    tokens: list[Token] = []
    i = 0
    while i < len(s):
        if s[i].isspace():
            i += 1
        elif s[i].isdigit():
            j = i
            while j < len(s) and s[j].isdigit():
                j += 1
            tokens.append(Num(kind="Num", value=int(s[i:j])))
            i = j
        elif s[i].islower() or s[i] == '_':
            j = i + 1
            while j < len(s) and (s[j].islower() or s[j].isdigit() or s[j] == '_'):
                j += 1
            tokens.append(Ident(kind="Ident", name=s[i:j]))
            i = j
        elif s[i:i+2] in ("==", "<=", ">=", "!="):
            tokens.append(Sym(kind="Sym", text=s[i:i+2]))
            i += 2
        elif s[i] in "+-*/=<>,()":
            tokens.append(Sym(kind="Sym", text=s[i]))
            i += 1
        else:
            return Err(ok=False, error=f"unexpected character: {s[i]} at {i}")
    return Ok(ok=True, value=tokens)

