class Coin(TypedDict):
    kind: Literal["Coin"]
    cents: int

class Select(TypedDict):
    kind: Literal["Select"]
    price: int

class Refund(TypedDict):
    kind: Literal["Refund"]

Event = Coin | Select | Refund

def vending_machine(events: list[Event]) -> list[str]:
    credit = 0
    messages = []

    for event in events:
        if event["kind"] == "Coin":
            if event["cents"] in [5, 10, 25, 100]:
                credit += event["cents"]
            else:
                messages.append(f"reject {event['cents']}")
        elif event["kind"] == "Select":
            if credit >= event["price"]:
                messages.append(f"vend {event['price']} change {credit - event['price']}")
                credit = 0
            else:
                messages.append(f"insufficient {credit}")
        elif event["kind"] == "Refund":
            if credit > 0:
                messages.append(f"refund {credit}")
                credit = 0

    if credit > 0:
        messages.append(f"refund {credit}")

    return messages

from __future__ import annotations

def wrap_text(s: str, width: int) -> list[str]:
    words = s.split()
    lines = []
    current_line = ""

    for word in words:
        if len(current_line) + len(word) + 1 <= width:
            if current_line:
                current_line += " " + word
            else:
                current_line = word
        else:
            lines.append(current_line)
            current_line = word

    if current_line:
        lines.append(current_line)

    return lines

