class Swap(TypedDict):
    kind: Literal["Swap"]
    __match_args__ = ()

class Jz(TypedDict):
    kind: Literal["Jz"]
    target: int
    __match_args__ = ("target",)

class Jmp(TypedDict):
    kind: Literal["Jmp"]
    target: int
    __match_args__ = ("target",)

class Print(TypedDict):
    kind: Literal["Print"]
    __match_args__ = ()

class Halt(TypedDict):
    kind: Literal["Halt"]
    __match_args__ = ()

Instr = Push | Pop | Add | Sub | Mul | Dup | Swap | Jz | Jmp | Print | Halt

def stack_vm(prog: list[Instr]) -> Ok[list[int]] | Err:
    stack: list[int] = []
    output: list[int] = []
    pc: int = 0
    steps: int = 0
    max_steps: int = 1000

    while pc < len(prog):
        if steps >= max_steps:
            return Err({"ok": False, "error": "step limit exceeded"})
        steps += 1

        instr = prog[pc]
        match instr:
            case Push(n):
                stack.append(n)
            case Pop():
                if not stack:
                    return Err({"ok": False, "error": f"stack underflow at {pc}"})
                stack.pop()
            case Add():
                if len(stack) < 2:
                    return Err({"ok": False, "error": f"stack underflow at {pc}"})
                stack.append(stack.pop() + stack.pop())
            case Sub():
                if len(stack) < 2:
                    return Err({"ok": False, "error": f"stack underflow at {pc}"})
                b, a = stack.pop(), stack.pop()
                stack.append(a - b)
            case Mul():
                if len(stack) < 2:
                    return Err({"ok": False, "error": f"stack underflow at {pc}"})
                stack.append(stack.pop() * stack.pop())
            case Dup():
                if not stack:
                    return Err({"ok": False, "error": f"stack underflow at {pc}"})
                stack.append(stack[-1])
            case Swap():
                if len(stack) < 2:
                    return Err({"ok": False, "error": f"stack underflow at {pc}"})
                stack[-1], stack[-2] = stack[-2], stack[-1]
            case Jz(target):
                if not stack:
                    return Err({"ok": False, "error": f"stack underflow at {pc}"})
                if stack.pop() == 0:
                    pc = target
                    continue
            case Jmp(target):
                if target < 0 or target >= len(prog):
                    return Err({"ok": False, "error": f"bad jump at {pc}"})
                pc = target
                continue
            case Print():
                if not stack:
                    return Err({"ok": False, "error": f"stack underflow at {pc}"})
                output.append(stack.pop())
            case Halt():
                break
        pc += 1

    return Ok({"ok": True, "value": output})

fn anagram_groups(words: List[String]) -> List[List[String]] {
  let mut map = Map[String, List[String]]()
  for word in words {
    let mut chars = word.chars().collect::<Vec<char>>()
    chars.sort()
    let sorted_word = String::from_iter(chars)
    map_set(map, sorted_word, append(map_get(map, sorted_word).unwrap_or(List[]), word))
  }
  return filter(map_values(map), |group| len(group) > 1)
}

