fn max_widths(rows: List[List[String]]) -> List[Int] {
  let widths = rows
    |> map(|row| row
      |> map(|cell| str_len(cell))
      |> fold(0, |max, width| max > width ? max : width))
  return widths
}

fn align_columns(rows: List[List[String]]) -> List[String] {
  let widths = max_widths(rows)
  return rows
    |> map(|row| row
      |> map(|cell| cell + repeat(" ", widths[str_len(cell)] - str_len(cell)))
      |> join(" | ")
      |> trim_right())
}

