type Person {
  name: String,
  age: Int,
}

fn age_histogram(people: List[Person], width: Int) -> Result[List[(String, Int)], String] {
  if width < 1 {
    return Err("bad width".to_string());
  }

  let mut counts = Map[String, Int]();
  for person in people {
    if person.age < 0 {
      return Err(format!("negative age: {}", person.name));
    }
    let bucket = (person.age / width) * width;
    let label = format!("{}-{}", bucket, bucket + width - 1);
    counts = map_set(counts, label, match map_get(counts, label) {
      Some(count) => count + 1,
      None => 1,
    });
  }

  let mut result = List[(String, Int)]();
  let mut min_bucket = i32::MAX;
  let mut max_bucket = i32::MIN;
  for person in people {
    let bucket = (person.age / width) * width;
    if bucket < min_bucket {
      min_bucket = bucket;
    }
    if bucket > max_bucket {
      max_bucket = bucket;
    }
  }
  for bucket in min_bucket..=max_bucket {
    let label = format!("{}-{}", bucket, bucket + width - 1);
    result = append(result, (label, match map_get(counts, label) {
      Some(count) => count,
      None => 0,
    }));
  }

  Ok(result)
}

