type Bracket = 
  | Paren
  | Square
  | Curly

fn match_bracket(b: Bracket) -> Bracket {
  match b {
    Paren => Paren,
    Square => Square,
    Curly => Curly,
  }
}

fn bracket_depth(s: String) -> Result[Int, String] {
  var depth = 0
  var max_depth = 0
  var stack: List[Bracket] = []

  for (i, c) in enumerate(s) {
    match c {
      '(' => {
        stack = append(stack, Paren)
        depth = depth + 1
        max_depth = max(max_depth, depth)
      },
      ')' => {
        if stack == [] || match_bracket(stack.last()) != Paren {
          return Err(format("mismatch at {}", i))
        }
        stack = drop(stack, 1)
        depth = depth - 1
      },
      '[' => {
        stack = append(stack, Square)
        depth = depth + 1
        max_depth = max(max_depth, depth)
      },
      ']' => {
        if stack == [] || match_bracket(stack.last()) != Square {
          return Err(format("mismatch at {}", i))
        }
        stack = drop(stack, 1)
        depth = depth - 1
      },
      '{' => {
        stack = append(stack, Curly)
        depth = depth + 1
        max_depth = max(max_depth, depth)
      },
      '}' => {
        if stack == [] || match_bracket(stack.last()) != Curly {
          return Err(format("mismatch at {}", i))
        }
        stack = drop(stack, 1)
        depth = depth - 1
      },
      _ => {},
    }
  }

  if stack != [] {
    return Err("unclosed at end".to_string())
  }

  return Ok(max_depth)
}

