  | Withdraw(name: String, amount: Int)
  | Transfer(src: String, dst: String, amount: Int)

fn bank_ledger(ops: List[BankOp]) -> Result[List[(String, Int)], String] {
  var accounts = Map[String, Int]()

  for (i, op) in enumerate(ops) {
    match op {
      Open(name) => {
        if map_get(accounts, name) != null {
          return Err("step " + to_string(i + 1) + ": duplicate account " + name)
        }
        map_set(accounts, name, 0)
      },
      Deposit(name, amount) => {
        if amount <= 0 {
          return Err("step " + to_string(i + 1) + ": invalid amount")
        }
        if map_get(accounts, name) == null {
          return Err("step " + to_string(i + 1) + ": unknown account " + name)
        }
        map_set(accounts, name, map_get(accounts, name)! + amount)
      },
      Withdraw(name, amount) => {
        if amount <= 0 {
          return Err("step " + to_string(i + 1) + ": invalid amount")
        }
        if map_get(accounts, name) == null {
          return Err("step " + to_string(i + 1) + ": unknown account " + name)
        }
        if map_get(accounts, name)! < amount {
          return Err("step " + to_string(i + 1) + ": insufficient funds")
        }
        map_set(accounts, name, map_get(accounts, name)! - amount)
      },
      Transfer(src, dst, amount) => {
        if amount <= 0 {
          return Err("step " + to_string(i + 1) + ": invalid amount")
        }
        if src == dst {
          return Err("step " + to_string(i + 1) + ": same account")
        }
        if map_get(accounts, src) == null {
          return Err("step " + to_string(i + 1) + ": unknown account " + src)
        }
        if map_get(accounts, dst) == null {
          return Err("step " + to_string(i + 1) + ": unknown account " + dst)
        }
        if map_get(accounts, src)! < amount {
          return Err("step " + to_string(i + 1) + ": insufficient funds")
        }
        map_set(accounts, src, map_get(accounts, src)! - amount)
        map_set(accounts, dst, map_get(accounts, dst)! + amount)
      },
    }
  }

  return Ok(map_to_list(accounts))
}

