fn caesar_shift(s: String, k: Int) -> String {
  let mut result = String::new();
  for c in s.chars() {
    if c.is_ascii_lowercase() {
      let shifted = ((c as u8 - b'a' + k as u8 + 26) % 26) + b'a';
      result.push(shifted as char);
    } else {
      result.push(c);
    }
  }
  result
}

