type Cell = (Int, Int)

fn is_valid(grid: List[String], cell: Cell) -> Bool {
  let (x, y) = cell
  x >= 0 && x < len(grid) && y >= 0 && y < str_len(grid[0])
}

fn is_land(grid: List[String], cell: Cell) -> Bool {
  let (x, y) = cell
  grid[x][y] == '#'
}

fn dfs(grid: List[String], cell: Cell, visited: Map[Cell, Bool]) -> Int {
  if !is_valid(grid, cell) || visited[cell] || !is_land(grid, cell) {
    return 0
  }
  visited = map_set(visited, cell, true)
  let (x, y) = cell
  let directions = [(0, 1), (1, 0), (0, -1), (-1, 0)]
  let mut size = 1
  for dir in directions {
    let (dx, dy) = dir
    size = size + dfs(grid, (x + dx, y + dy), visited)
  }
  return size
}

fn count_islands(grid: List[String]) -> (Int, Int) {
  let mut visited = map_from([])
  let mut island_count = 0
  let mut max_size = 0
  for (i, row) in enumerate(grid) {
    for (j, cell) in enumerate(row) {
      let cell = (i, j)
      if is_valid(grid, cell) && !visited[cell] && is_land(grid, cell) {
        island_count = island_count + 1
        let size = dfs(grid, cell, visited)
        max_size = max(max_size, size)
      }
    }
  }
  return (island_count, max_size)
}

