type Shift {
  worker: String,
  start_hour: Int,
  end_hour: Int,
}

fn coverage_gaps(shifts: List[Shift], required: Int) -> List[Int] {
  let hours = range(0, 24)
  let coverage = map(hours, |h| {
    let workers = filter(shifts, |s| s.start_hour <= h && h < s.end_hour)
    let distinct_workers = map(workers, |s| s.worker)
    set_size(distinct_workers)
  })
  let gaps = filter(enumerate(hours), |(i, c)| c < required)
  map(gaps, |(i, _)| i)
}

fn set_size(set: List[String]) -> Int {
  let seen = map_from([])
  let count = fold(set, 0, |acc, w| {
    if !map_get(seen, w) {
      map_set(seen, w, true)
      acc + 1
    } else {
      acc
    }
  })
  count
}

