type Key =
  | Digit(d: Int)
  | Enter
  | Clear

type State =
  | Locked { buffer: String, failures: Int }
  | Open
  | Blocked

fn door_lock(code: String, events: List[Key]) -> String {
  let mut state = Locked { buffer: "", failures: 0 };

  for event in events {
    state = match state {
      Locked { buffer, failures } => match event {
        Digit(d) => {
          let new_buffer = if buffer.len() < code.len() {
            buffer + &d.to_string()
          } else {
            &buffer[1..] + &d.to_string()
          };
          Locked { buffer: new_buffer, failures }
        },
        Enter => {
          if buffer == code {
            Open
          } else {
            let failures = failures + 1;
            if failures >= 3 {
              Blocked
            } else {
              Locked { buffer: "", failures }
            }
          }
        },
        Clear => Locked { buffer: "", failures }
      },
      Open => match event {
        Enter => Locked { buffer: "", failures: 0 },
        _ => state
      },
      Blocked => state
    };
  }

  match state {
    Locked { .. } => "locked",
    Open => "open",
    Blocked => "blocked"
  }
}

