fn edit_script_distance(a: String, b: String) -> Int {
  let m = str_len(a);
  let n = str_len(b);
  let mut dp = List[List[Int]](map(range(0, m + 1), |i| map(range(0, n + 1), |_| 0)));

  for i in range(1, m + 1) {
    dp[i][0] = i;
  }

  for j in range(1, n + 1) {
    dp[0][j] = j;
  }

  for i in range(1, m + 1) {
    for j in range(1, n + 1) {
      let cost = if a[i - 1] == b[j - 1] { 0 } else { 1 };
      dp[i][j] = min(
        dp[i - 1][j] + 1, // delete
        min(
          dp[i][j - 1] + 1, // insert
          min(
            dp[i - 1][j - 1] + cost, // replace
            dp[i - 2][j - 2] + cost if i > 1 && j > 1 && a[i - 2] == b[j - 1] && a[i - 1] == b[j - 2] else i32::MAX // swap
          )
        )
      );
    }
  }

  return dp[m][n];
}

