  let unique_requests = requests |> filter(|r| r != start) |> sort_by(|r| r) |> unique();
  let mut result = if direction == "up" {
    [start].concat(unique_requests.filter(|r| r > start))
  } else {
    [start].concat(unique_requests.filter(|r| r < start).reverse())
  };
  if direction == "up" {
    result = result.concat(unique_requests.filter(|r| r > start).reverse())
  } else {
    result = result.concat(unique_requests.filter(|r| r < start))
  }
  return result;
}

