fn find_all(s: String, pat: String) -> List[Int] {
  if str_len(pat) == 0 {
    return []
  }
  var result = []
  var i = 0
  while i <= str_len(s) - str_len(pat) {
    if s[i..i+str_len(pat)] == pat {
      result = append(result, i)
    }
    i = i + 1
  }
  return result
}

