    [(day_start, sorted_meetings[0].start)]
  } else {
    []
  };

  for i in 1..sorted_meetings.len() {
    if sorted_meetings[i].start > sorted_meetings[i - 1].end {
      free_slots = free_slots.append((sorted_meetings[i - 1].end, sorted_meetings[i].start));
    }
  }

  if sorted_meetings.last().unwrap().end < day_end {
    free_slots = free_slots.append((sorted_meetings.last().unwrap().end, day_end));
  }

  return free_slots;
}

