fn flatten_nested(s: String) -> Result[(List[Int], Int), String] {
  let s = s.replace(" ", "");
  let mut stack = List[Step]();
  let mut result = List[Int]();
  let mut depth = 0;
  let mut max_depth = 0;

  for (i, c) in enumerate(s) {
    match c {
      '[' => {
        depth += 1;
        max_depth = max(max_depth, depth);
        stack.push(Call("list".to_string()));
      },
      ']' => {
        depth -= 1;
        let mut list = List[Int]();
        while let Some(Step::Answer(val)) = stack.pop() {
          list = prepend(val, list);
        }
        result = prepend(list, result);
      },
      ',' => continue,
      '-' | '0'..='9' => {
        let mut num = 0;
        let mut neg = false;
        if c == '-' {
          neg = true;
          i += 1;
        }
        while i < s.len() && s[i] >= '0' && s[i] <= '9' {
          num = num * 10 + (s[i] as u8 - b'0') as Int;
          i += 1;
        }
        if neg {
          num = -num;
        }
        stack.push(Answer(num));
        i -= 1;
      },
      _ => return Err(format!("invalid at {}", i)),
    }
  }

  if depth != 0 {
    return Err(format!("invalid at {}", s.len()));
  }

  Ok((result, max_depth))
}

type Step = Call(String) | Answer(Int);

