fn glob_match(pattern: String, s: String) -> Bool {
  fn match_char(p: Char, c: Char) -> Bool {
    if p == '?' { return true; }
    if p == '\\' { return p == c; }
    return p == c;
  }

  fn match_segment(pattern: String, s: String) -> Bool {
    let mut i = 0;
    for p in pattern.chars() {
      if p == '*' {
        if i == s.len() { return true; }
        for j in i..s.len() {
          if match_segment(pattern[i..].to_string(), s[j..].to_string()) {
            return true;
          }
        }
        return false;
      } else if i >= s.len() || !match_char(p, s.chars().nth(i).unwrap()) {
        return false;
      }
      i += 1;
    }
    return i == s.len();
  }

  match_segment(pattern, s)
}

