fn eval_expr(s: String) -> Result[Int, String] {
  let s = s.replace(" ", "");
  let result = parse_expr(&s, 0);
  match result {
    Ok((value, _)) => Ok(value),
    Err(e) => Err(e),
  }
}

fn parse_expr(s: &str, pos: usize) -> Result<(Int, usize), String> {
  let (term, pos) = parse_term(s, pos)?;
  parse_expr_tail(term, s, pos)
}

fn parse_expr_tail(acc: Int, s: &str, pos: usize) -> Result<(Int, usize), String> {
  loop {
    if pos >= s.len() {
      return Ok((acc, pos));
    }
    let c = s.chars().nth(pos).unwrap();
    if c == '+' {
      let (term, pos) = parse_term(s, pos + 1)?;
      acc = acc + term;
    } else if c == '-' {
      let (term, pos) = parse_term(s, pos + 1)?;
      acc = acc - term;
    } else {
      return Ok((acc, pos));
    }
  }
}

fn parse_term(acc: Int, s: &str, pos: usize) -> Result<(Int, usize), String> {
  let (factor, pos) = parse_factor(s, pos)?;
  parse_term_tail(acc * factor, s, pos)
}

fn parse_term_tail(acc: Int, s: &str, pos: usize) -> Result<(Int, usize), String> {
  loop {
    if pos >= s.len() {
      return Ok((acc, pos));
    }
    let c = s.chars().nth(pos).unwrap();
    if c == '*' {
      let (factor, pos) = parse_factor(s, pos + 1)?;
      acc = acc * factor;
    } else if c == '/' {
      let (factor, pos) = parse_factor(s, pos + 1)?;
      if factor == 0 {
        return Err("division by zero".to_string());
      }
      acc = acc / factor;
    } else {
      return Ok((acc, pos));
    }
  }
}

fn parse_factor(s: &str, pos: usize) -> Result<(Int, usize), String> {
  if pos >= s.len() {
    return Err("unexpected end".to_string());
  }
  let c = s.chars().nth(pos).unwrap();
  if c == '(' {
    let (value, pos) = parse_expr(s, pos + 1)?;
    if pos >= s.len() || s.chars().nth(pos).unwrap() != ')' {
      return Err("unexpected end".to_string());
    }
    Ok((value, pos + 1))
  } else if c.is_digit(10) {
    let mut end = pos + 1;
    while end < s.len() && s.chars().nth(end).unwrap().is_digit(10) {
      end += 1;
    }
    let value = s[pos..end].parse::<Int>().unwrap();
    Ok((value, end))
  } else {
    return Err(format!("unexpected character: {}", c));
  }
}

