type Stock {
  sku: String,
  qty: Int,
}

type Txn {
  sku: String,
  delta: Int,
}

fn inventory_ledger(stock: List[Stock], txns: List[Txn]) -> Result[List[Stock], String] {
  let mut ledger = stock;
  for (i, txn) in enumerate(txns) {
    let mut found = false;
    for s in &mut ledger {
      if s.sku == txn.sku {
        s.qty = s.qty + txn.delta;
        found = true;
        if s.qty < 0 {
          return Err(format!("txn {}: {} would go negative", i + 1, txn.sku));
        }
        break;
      }
    }
    if !found {
      return Err(format!("txn {}: unknown sku {}", i + 1, txn.sku));
    }
  }
  ledger = ledger.filter(|s| s.qty > 0);
  ledger.sort_by(|a, b| a.sku.cmp(&b.sku));
  Ok(ledger)
}

