fn count_frequencies(xs: List[Int]) -> Map[Int, Int] {
  return fold(xs, map_from([]), |m, x| map_set(m, x, 1 + map_get(m, x).unwrap_or(0)))
}

fn sort_by_count(m: Map[Int, Int]) -> List[(Int, Int)] {
  return sort_by(map_to_list(m), |a, b| (b.1, a.0))
}

fn k_most_frequent(xs: List[Int], k: Int) -> List[(Int, Int)] {
  if k <= 0 {
    return []
  }
  let freqs = count_frequencies(xs)
  return take(sort_by_count(freqs), k)
}

