  ms: Int,
  status: Int,
}

fn latency_report(entries: List[Request]) -> List[(String, Int, Int, Int)] {
  let grouped = group_by(entries, |r| r.endpoint);
  let mut result = List[(String, Int, Int, Int)]();
  for (endpoint, requests) in grouped {
    let count = len(requests);
    let mut ms_values = List[Int]();
    let mut error_count = 0;
    for r in requests {
      ms_values = append(ms_values, r.ms);
      if r.status >= 500 {
        error_count = error_count + 1;
      }
    }
    ms_values = sort_by(ms_values, |a| a);
    let p90_index = (9 * count + 9) / 10 - 1;
    let p90 = ms_values[p90_index];
    result = append(result, (endpoint, count, p90, error_count));
  }
  return result;
}

