type Line {
  sku: String,
  qty: Int,
  unit_cents: Int,
}

fn invoice_total(lines: List[Line], coupon: String) -> Result[Int, String] {
  if lines.length > 0 {
    let first_bad_line = lines.find(|l| l.qty < 1);
    if first_bad_line.is_some() {
      return Err("bad quantity: " + first_bad_line.unwrap().sku);
    }
  }

  let mut subtotal = 0;
  for line in lines {
    let amount = line.qty * line.unit_cents;
    if line.qty >= 10 {
      subtotal = subtotal + (amount - (amount / 10));
    } else {
      subtotal = subtotal + amount;
    }
  }

  let mut amount = subtotal;
  if coupon == "SAVE500" {
    amount = amount - 500;
    if amount < 0 {
      amount = 0;
    }
  } else if coupon == "PCT10" {
    amount = amount - (subtotal / 10);
  } else if coupon == "BIG20" {
    if subtotal >= 10000 {
      amount = amount - (subtotal / 5);
    } else {
      return Err("coupon not applicable: BIG20");
    }
  } else if coupon != "" {
    return Err("unknown coupon: " + coupon);
  }

  let tax = ((amount * 8) + 50) / 100;
  amount = amount + tax;
  return Ok(amount);
}

