type Match {
  home: String,
  away: String,
  home_goals: Int,
  away_goals: Int,
}

fn league_table(matches: List[Match]) -> List[(String, Int, Int, Int)] {
  var table = Map[String, (Int, Int, Int)]()

  for m in matches {
    let update = |team: String, goals_for: Int, goals_against: Int| {
      let (points, goal_difference, goals) = table.get(team).unwrap_or((0, 0, 0))
      table.set(team, (points + (if goals_for > goals_against { 3 } else if goals_for == goals_against { 1 } else { 0 }), goal_difference + goals_for - goals_against, goals + goals_for))
    }

    update(m.home, m.home_goals, m.away_goals)
    update(m.away, m.away_goals, m.home_goals)
  }

  return table
    |> keys
    |> sort_by(|team| (-table.get(team).unwrap().0, -table.get(team).unwrap().1, -table.get(team).unwrap().2, team))
    |> map(|team| (team, table.get(team).unwrap().0, table.get(team).unwrap().1, table.get(team).unwrap().2))
}

