        if grid[i][j] == "#" {
          count = count + 1;
        }
      }
    }
  }
  return count;
}

fn life_step(grid: List[String], steps: Int) -> List[String] {
  let rows = len(grid);
  let cols = str_len(grid[0]);
  for _ in range(0, steps) {
    let new_grid = map(grid, |row| {
      let chars = row.chars().collect();
      map(chars, |cell| {
        let live_neighbors = count_live_neighbors(grid, chars.index_of(cell), chars.index_of(cell));
        if cell == "#" {
          if live_neighbors == 2 || live_neighbors == 3 {
            return "#";
          } else {
            return ".";
          }
        } else {
          if live_neighbors == 3 {
            return "#";
          } else {
            return ".";
          }
        }
      }).join("")
    });
    grid = new_grid;
  }
  return grid;
}

