fn max_subarray(xs: List[Int]) -> Option[(Int, Int, Int)] {
  if xs == [] {
    return None
  }

  let max_sum = xs[0]
  let start = 0
  let end = 0
  let current_sum = xs[0]
  let current_start = 0

  for (i, &x) in enumerate(xs[1..]) {
    if current_sum < 0 {
      current_sum = x
      current_start = i + 1
    } else {
      current_sum = current_sum + x
    }

    if current_sum > max_sum {
      max_sum = current_sum
      start = current_start
      end = i + 1
    }
  }

  return Some((max_sum, start, end))
}

