  phone: String,
}

fn merge_contacts(contacts: List[Contact]) -> List[Contact] {
  let by_email = map_from(contacts.map(|c| (trim(c.email), c)));
  let by_phone = map_from(contacts.map(|c| (reduced_phone(c.phone), c)));

  let mut merged = Vec::new();
  let mut seen = Set::new();

  for c in contacts {
    if seen.contains(&c.email) || seen.contains(&reduced_phone(c.phone)) {
      continue;
    }

    let mut merged_contact = c;
    let mut email = trim(c.email);
    let mut phone = reduced_phone(c.phone);

    for (e, contact) in by_email {
      if e == email {
        seen.insert(e);
        merged_contact = merge_contact(merged_contact, contact);
        email = trim(contact.email);
        phone = reduced_phone(contact.phone);
      }
    }

    for (p, contact) in by_phone {
      if p == phone {
        seen.insert(p);
        merged_contact = merge_contact(merged_contact, contact);
        email = trim(contact.email);
        phone = reduced_phone(contact.phone);
      }
    }

    merged.push(merged_contact);
  }

  merged
}

