type OrderEvent =
  | Create(id: String)
  | Pay(id: String)
  | Ship(id: String)
  | Cancel(id: String)

type OrderState = 
  | Created
  | Paid
  | Shipped
  | Cancelled

fn order_state(event: OrderEvent) -> OrderState {
  match event {
    Create(_) => Created,
    Pay(_) => Paid,
    Ship(_) => Shipped,
    Cancel(_) => Cancelled,
  }
}

fn order_states(events: List[OrderEvent]) -> Result[List[(String, String)], String] {
  var orders: Map[String, OrderState] = map_from([])
  for event in events {
    let id = match event {
      Create(id) | Pay(id) | Ship(id) | Cancel(id) => id,
    };
    let current_state = match map_get(orders, id) {
      Some(state) => state,
      None => return Err("unknown order: " + id),
    };
    let new_state = order_state(event);
    if current_state == new_state {
      return Err("cannot " + match event {
        Pay(_) => "pay",
        Ship(_) => "ship",
        Cancel(_) => "cancel",
        _ => unreachable,
      } + " " + id + " from " + match current_state {
        Created => "created",
        Paid => "paid",
        Shipped => "shipped",
        Cancelled => "cancelled",
      });
    }
    map_set(orders, id, new_state);
  }
  return Ok(map_to_list(orders)
    |> sort_by(|(_, state)| match state {
      Created => 0,
      Paid => 1,
      Shipped => 2,
      Cancelled => 3,
    })
    |> map(|(id, state)| (id, match state {
      Created => "created",
      Paid => "paid",
      Shipped => "shipped",
      Cancelled => "cancelled",
    })));
}

