type Park =
  | Arrive(plate: String, minute: Int)
  | Leave(plate: String, minute: Int)

fn parking_fees(events: List[Park]) -> List[(String, Int)] {
  var parked = Map[String, Int]()
  var fees = Map[String, Int]()

  for e in events {
    match e {
      | Arrive(plate, minute) => {
        if !map_contains(parked, plate) {
          map_set(parked, plate, minute)
        }
      }
      | Leave(plate, minute) => {
        if map_contains(parked, plate) {
          let start = map_get(parked, plate)
          let duration = minute - start
          let fee = if duration <= 30 { 0 } else { 200 * ((duration - 30 + 59) // 60) }
          fee = if fee > 1000 { 1000 } else { fee }
          map_set(fees, plate, map_get(fees, plate) + fee)
          map_remove(parked, plate)
        }
      }
    }
  }

  return map_to_list(fees)
    |> sort_by(|(plate, _)| plate)
}

