fn parse_csv_line(s: String) -> Result[List[String], String] {
  let mut result = List[String]{};
  let mut chars = s.chars().peekable();
  let mut field = String{};
  let mut in_quote = false;

  while let Some(c) = chars.next() {
    if c == '"' {
      if in_quote {
        if let Some('"') = chars.peek() {
          field.push('"');
          chars.next();
        } else {
          return Err("unterminated quote".to_string());
        }
      } else {
        in_quote = true;
      }
    } else if c == ',' {
      if in_quote {
        return Err(format!("expected comma at {}", s.find('"').unwrap()));
      }
      result.push(field);
      field = String{};
    } else {
      field.push(c);
    }
  }

  if in_quote {
    return Err("unterminated quote".to_string());
  }

  if !field.is_empty() {
    result.push(field);
  }

  Ok(result)
}

