fn parse_duration(s: String) -> Result[Int, String] {
  if str_len(s) == 0 {
    return Err("empty".to_string());
  }

  let mut seconds = 0;
  let mut seen_units = 0;
  let mut i = 0;

  while i < str_len(s) {
    let mut num = 0;
    let mut j = i;

    while j < str_len(s) && s[j] >= '0' && s[j] <= '9' {
      num = num * 10 + (s[j] - '0' as u8) as Int;
      j += 1;
    }

    if j == i {
      return Err(format!("missing number before {}", s[j]));
    }

    i = j;

    if i == str_len(s) {
      return Err("missing unit".to_string());
    }

    let unit = s[i];
    i += 1;

    if unit == 'h' {
      if seen_units & 1 != 0 {
        return Err("unit out of order: h".to_string());
      }
      seconds += num * 3600;
      seen_units |= 1;
    } else if unit == 'm' {
      if seen_units & 2 != 0 {
        return Err("unit out of order: m".to_string());
      }
      seconds += num * 60;
      seen_units |= 2;
    } else if unit == 's' {
      if seen_units & 4 != 0 {
        return Err("unit out of order: s".to_string());
      }
      seconds += num;
      seen_units |= 4;
    } else {
      return Err(format!("unknown unit: {}", unit));
    }
  }

  Ok(seconds)
}

