fn parse_query(s: String) -> Result[List[(String, String)], String] {
  let items = s.split('&').filter(|i| !i.is_empty()).map(|i| i.split_once('=')).collect::<List<Option<(String, String)>>>();
  let mut pairs = List::new();
  for item in items {
    match item {
      Some((key, value)) => {
        let key = key.replace('+', " ");
        let value = value.replace('+', " ");
        if key.is_empty() {
          return Err(format!("empty key: {}", item));
        }
        pairs = pairs.append((key, value));
      },
      None => continue,
    }
  }
  return Ok(pairs);
}

