fn parse_money(s: String) -> Result[Int, String] {
  let s = s.trim();
  let mut negative = false;
  if s.starts_with('-') {
    negative = true;
    s = &s[1..];
  }
  if !s.starts_with('$') {
    return Err("missing $".to_string());
  }
  s = &s[1..];
  let parts: Vec<&str> = s.split('.').collect();
  if parts.len() != 2 {
    return Err("bad cents".to_string());
  }
  let dollars = parts[0];
  let cents = parts[1];
  if cents.len() != 2 {
    return Err("bad cents".to_string());
  }
  let dollars_int = match dollars.parse::<Int>() {
    Ok(d) => d,
    Err(_) => return Err("bad dollars".to_string()),
  };
  let cents_int = match cents.parse::<Int>() {
    Ok(c) => c,
    Err(_) => return Err("bad dollars".to_string()),
  };
  let total = dollars_int * 100 + cents_int;
  if negative {
    Ok(-total)
  } else {
    Ok(total)
  }
}

