type Employee {
  name: String,
  dept: String,
  hours: Int,
  rate_cents: Int,
}

fn payroll_by_dept(emps: List[Employee]) -> List[(String, Int)] {
  let by_dept = group_by(emps, |e| e.dept);
  let mut results = map_from([]);

  for (dept, es) in by_dept {
    let mut total = 0;
    for e in es {
      let regular = min(e.hours, 40) * e.rate_cents;
      let overtime = max(0, e.hours - 40) * e.rate_cents * 3 / 2;
      total = total + regular + overtime;
    }
    map_set(results, dept, total);
  }

  let mut sorted = map_to_list(results);
  sorted.sort_by(|a, b| {
    if a.1 != b.1 {
      b.1 - a.1
    } else {
      str_compare(a.0, b.0)
    }
  });

  return sorted;
}

