fn rle_decode(s: String) -> Result<String, String> {
  let mut result = String::new();
  let mut chars = s.chars().peekable();

  while let Some(c) = chars.next() {
    if c.is_digit(10) {
      return Err("missing character before count".to_string());
    }

    let mut count = 1;
    if let Some(&next) = chars.peek() {
      if next.is_digit(10) {
        count = chars.take_while(|&c| c.is_digit(10)).fold(0, |acc, c| acc * 10 + c.to_digit(10).unwrap());
      }
    }

    if count == 0 {
      return Err(format!("bad count for {}", c));
    }

    result.push_str(&c.to_string().repeat(count));
  }

  Ok(result)
}

