  kind: String,
  time: Int,
}

fn session_totals(events: List[Session]) -> List[(String, Int)] {
  var sessions = map_from([])
  var last_time = 0

  for e in events {
    if e.kind == "login" {
      if !map_contains(sessions, e.user) {
        map_set(sessions, e.user, (e.time, 0))
      }
    } else if e.kind == "logout" {
      if map_contains(sessions, e.user) {
        let (login_time, total) = map_get(sessions, e.user)
        map_set(sessions, e.user, (login_time, total + e.time - login_time))
      }
    }
    last_time = e.time
  }

  for (user, (login_time, total)) in sessions {
    if login_time < last_time {
      map_set(sessions, user, (login_time, total + last_time - login_time))
    }
  }

  return map_to_list(sessions)
}

