type Expense {
  payer: String,
  amount_cents: Int,
}

fn total_expenses(expenses: List[Expense]) -> Int {
  return expenses |> map(|e| e.amount_cents) |> sum();
}

fn settle_debts(expenses: List[Expense], people: List[String]) -> List[(String, String, Int)] {
  let total = total_expenses(expenses);
  let per_person = total / people.len();
  let remainder = total % people.len();
  let mut balances = people.map(|_| 0);
  let mut payments = [];

  for i in range(0, remainder) {
    balances[i] = balances[i] + 1;
  }

  for p in people {
    balances[people.index_of(p)] = balances[people.index_of(p)] - per_person;
  }

  while balances.contains(|b| b != 0) {
    let debtor = people.find(|p| balances[people.index_of(p)] < 0);
    let creditor = people.find(|p| balances[people.index_of(p)] > 0);
    let amount = min(-balances[people.index_of(debtor)], balances[people.index_of(creditor)]);
    payments = payments.append((debtor, creditor, amount));
    balances[people.index_of(debtor)] = balances[people.index_of(debtor)] + amount;
    balances[people.index_of(creditor)] = balances[people.index_of(creditor)] - amount;
  }

  return payments;
}

