fn sliding_window_max(xs: List[Int], k: Int) -> Result[List[Int], String] {
  if k < 1 {
    return Err("window must be positive".to_string());
  }
  if k > xs.len() {
    return Err("window larger than input".to_string());
  }
  let mut result = List[Int]{};
  for i in range(0, xs.len() - k + 1) {
    let window = xs.slice(i, i + k);
    let max = window.fold(0, |acc, &x| if x > acc { x } else { acc });
    result = result.append(max);
  }
  return Ok(result);
}

