type Student {
  name: String,
  scores: List[Int],
}

fn median(scores: List[Int]) -> Option[Float] {
  let sorted = sort(scores);
  let len = len(sorted);
  if len == 0 {
    return None;
  }
  let mid = len / 2;
  if len % 2 == 0 {
    Some((to_float(sorted[mid - 1]) + to_float(sorted[mid])) / 2.0)
  } else {
    Some(to_float(sorted[mid]))
  }
}

fn student_medians(students: List[Student]) -> List[(String, Float)] {
  students
    |> filter(|s| len(s.scores) > 0)
    |> map(|s| (s.name, median(s.scores).unwrap_or(0.0)))
    |> sort_by(|a, b| if a.1 == b.1 { compare(a.0, b.0) } else { compare(b.1, a.1) })
}

