type EditOp =
  | Insert(text: String)
  | Delete(n: Int)
  | Left(n: Int)
  | Right(n: Int)
  | Undo

fn text_editor(ops: List[EditOp]) -> String {
  var text = ""
  var cursor = 0
  var history = []

  for op in ops {
    match op {
      Insert(t) => {
        history = (text, cursor) :: history
        text = text[0..cursor] + t + text[cursor..]
        cursor = cursor + str_len(t)
      },
      Delete(n) => {
        history = (text, cursor) :: history
        let remove = min(n, cursor)
        text = text[0..cursor-remove] + text[cursor..]
        cursor = cursor - remove
      },
      Left(n) => {
        cursor = max(0, cursor - n)
      },
      Right(n) => {
        cursor = min(str_len(text), cursor + n)
      },
      Undo => {
        if !history.is_empty() {
          let (prev_text, prev_cursor) = history[0]
          text = prev_text
          cursor = prev_cursor
          history = history[1..]
        }
      },
    }
  }

  return text
}

