type Instr =
  | Push(n: Int)
  | Pop
  | Add
  | Sub
  | Mul
  | Dup
  | Swap
  | Jz(target: Int)
  | Jmp(target: Int)
  | Print
  | Halt

fn stack_vm(prog: List[Instr]) -> Result[List[Int], String] {
  requires: len(prog) <= 1000
  ensures: result.is_ok() || result.is_err()
{
  var stack: List[Int] = []
  var pc: Int = 0
  var steps: Int = 0

  while pc < len(prog) && steps < 1000 {
    steps = steps + 1
    let instr = prog[pc]
    match instr {
      Push(n) => stack = append(stack, n),
      Pop => {
        if len(stack) == 0 {
          return Err("stack underflow at " + to_string(pc))
        }
        stack = drop(stack, 1)
      },
      Add => {
        if len(stack) < 2 {
          return Err("stack underflow at " + to_string(pc))
        }
        let b = stack[0]
        let a = stack[1]
        stack = drop(stack, 2)
        stack = append(stack, a + b)
      },
      Sub => {
        if len(stack) < 2 {
          return Err("stack underflow at " + to_string(pc))
        }
        let b = stack[0]
        let a = stack[1]
        stack = drop(stack, 2)
        stack = append(stack, a - b)
      },
      Mul => {
        if len(stack) < 2 {
          return Err("stack underflow at " + to_string(pc))
        }
        let b = stack[0]
        let a = stack[1]
        stack = drop(stack, 2)
        stack = append(stack, a * b)
      },
      Dup => {
        if len(stack) == 0 {
          return Err("stack underflow at " + to_string(pc))
        }
        let a = stack[0]
        stack = append(stack, a)
      },
      Swap => {
        if len(stack) < 2 {
          return Err("stack underflow at " + to_string(pc))
        }
        let b = stack[0]
        let a = stack[1]
        stack = drop(stack, 2)
        stack = append(stack, b)
        stack = append(stack, a)
      },
      Jz(target) => {
        if len(stack) == 0 {
          return Err("stack underflow at " + to_string(pc))
        }
        let a = stack[0]
        stack = drop(stack, 1)
        if a == 0 {
          pc = target
        }
      },
      Jmp(target) => {
        if target < 0 || target >= len(prog) {
          return Err("bad jump at " + to_string(pc))
        }
        pc = target
      },
      Print => {
        if len(stack) == 0 {
          return Err("stack underflow at " + to_string(pc))
        }
        let a = stack[0]
        stack = drop(stack, 1)
        print(to_string(a))
      },
      Halt => return Ok(stack),
    }
    pc = pc + 1
  }

  if pc >= len(prog) {
    return Ok(stack)
  }

  return Err("step limit exceeded")
}

