    (Love, _) => Some(Fifteen),
    (Fifteen, _) => Some(Thirty),
    (Thirty, _) => Some(Forty),
    (Forty, _) => Some(AdvantageA),
    (AdvantageA, _) => Some(GameA),
    (AdvantageB, _) => Some(GameB),
    (Deuce, _) => Some(AdvantageA),
    (_, AdvantageA) => Some(GameA),
    (_, AdvantageB) => Some(GameB),
    _ => Some(Deuce),
  }
}

fn tennis_score(points: String) -> String {
  let mut a = Love;
  let mut b = Love;
  for p in points.chars() {
    match parse_point(p.to_string()) {
      Some(score) => {
        a = update_score(a, score);
        b = update_score(b, score);
      },
      None => return "error: bad point".to_string(),
    }
    if a == GameA || b == GameB {
      return match (a, b) {
        (GameA, _) => "game A".to_string(),
        (_, GameB) => "game B".to_string(),
        _ => unreachable!(),
      };
    }
  }
  match (a, b) {
    (Love, Love) => "love-all".to_string(),
    (Fifteen, Fifteen) => "15-all".to_string(),
    (Thirty, Thirty) => "30-all".to_string(),
    (Forty, Forty) => "40-all".to_string(),
    (AdvantageA, _) => "advantage A".to_string(),
    (_, AdvantageB) => "advantage B".to_string(),
    _ => unreachable!(),
  }
}

