class Person(TypedDict):
    name: str
    age: int

def age_histogram(people: list[Person], width: int) -> Ok[list[tuple[str, int]]] | Err:
    if width < 1:
        return Err(ok=False, error="bad width")

    age_counts: dict[int, int] = {}
    for person in people:
        if person['age'] < 0:
            return Err(ok=False, error=f"negative age: {person['name']}")
        bucket = (person['age'] // width) * width
        age_counts[bucket] = age_counts.get(bucket, 0) + 1

    result = []
    for bucket in sorted(age_counts.keys()):
        label = f"{bucket}-{bucket + width - 1}"
        count = age_counts[bucket]
        result.append((label, count))

    return Ok(ok=True, value=result)

type Token =
  | Num(value: Int)
  | Ident(name: String)
  | Sym(text: String)

fn tokenize(s: String) -> Result[List[Token], String] {
  let chars = s.chars().collect::<Vec<char>>();
  let mut tokens = Vec::new();
  let mut i = 0;

  while i < chars.len() {
    match chars[i] {
      '0'..='9' => {
        let mut num = 0;
        while i < chars.len() && chars[i].is_digit(10) {
          num = num * 10 + chars[i].to_digit(10).unwrap() as Int;
          i += 1;
        }
        tokens.push(Num(num));
      },
      'a'..='z' | '_' => {
        let mut name = String::new();
        while i < chars.len() && (chars[i].is_digit(10) || chars[i].is_alphabetic() || chars[i] == '_') {
          name.push(chars[i]);
          i += 1;
        }
        tokens.push(Ident(name));
      },
      '=' => {
        if i + 1 < chars.len() && chars[i + 1] == '=' {
          tokens.push(Sym("==".to_string()));
          i += 2;
        } else {
          tokens.push(Sym("=".to_string()));
          i += 1;
        }
      },
      '<' => {
        if i + 1 < chars.len() && chars[i + 1] == '=' {
          tokens.push(Sym("<=".to_string()));
          i += 2;
        } else {
          tokens.push(Sym("<".to_string()));
          i += 1;
        }
      },
      '>' => {
        if i + 1 < chars.len() && chars[i + 1] == '=' {
          tokens.push(Sym(">=".to_string()));
          i += 2;
        } else {
          tokens.push(Sym(">".to_string()));
          i += 1;
        }
      },
      '!' => {
        if i + 1 < chars.len() && chars[i + 1] == '=' {
          tokens.push(Sym("!=".to_string()));
          i += 2;
        } else {
          return Err(format!("unexpected character: {} at {}", chars[i], i));
        }
      },
      '+' | '-' | '*' | '/' | '(' | ')' | ',' => {
        tokens.push(Sym(chars[i].to_string()));
        i += 1;
      },
      _ => {
        return Err(format!("unexpected character: {} at {}", chars[i], i));
      },
    }
  }

  Ok(tokens)
}

