fn top_product_per_region(sales: List[Sale>) -> List[(String, String, Int)] {
  let mut revenue = Map[String, Map[String, Int]]()
  for sale in sales {
    let region_revenue = map_get(revenue, sale.region) |> unwrap_or(map())
    let product_revenue = map_get(region_revenue, sale.product) |> unwrap_or(0)
    map_set(region_revenue, sale.product, product_revenue + sale.units * sale.price_cents)
    map_set(revenue, sale.region, region_revenue)
  }
  let mut result = List[(String, String, Int)]()
  for (region, region_revenue) in revenue {
    let mut max_revenue = 0
    let mut top_product = ""
    for (product, product_revenue) in region_revenue {
      if product_revenue > max_revenue || (product_revenue == max_revenue && product < top_product) {
        max_revenue = product_revenue
        top_product = product
      }
    }
    result = append(result, (region, top_product, max_revenue))
  }
  return sort_by(result, |(region, _, _)| region)
}

