    end_hour: int

def coverage_gaps(shifts: list[Shift], required: int) -> list[int]:
    coverage = [0] * 24
    for shift in shifts:
        for hour in range(shift['start_hour'], shift['end_hour']):
            if 0 <= hour < 24:
