def bowling_score(rolls: list[int]) -> Ok[int] | Err:
    if any(r < 0 or r > 10 for r in rolls):
        return Err(ok=False, error="invalid roll")

    score = 0
    i = 0
    for frame in range(10):
        if i >= len(rolls):
            return Err(ok=False, error="incomplete game")

        if rolls[i] == 10:  # Strike
            score += 10 + sum(rolls[i+1:i+3])
            i += 1
        elif rolls[i] + rolls[i+1] > 10:  # Too many pins in frame
            return Err(ok=False, error=f"too many pins in frame {frame + 1}")
        else:  # Open frame
            score += rolls[i] + rolls[i+1]
            i += 2

    if i < len(rolls):
        return Err(ok=False, error="too many rolls")

    return Ok(ok=True, value=score)

