class Job(TypedDict):
    name: str
    deps: list[str]

def build_order(jobs: list[Job]) -> Ok[list[str]] | Err:
    job_map = {job['name']: job for job in jobs}
    if len(job_map) != len(jobs):
        first_duplicate = next(name for name, count in Counter([job['name'] for job in jobs]).items() if count > 1)
        return Err({"ok": False, "error": f"duplicate job: {first_duplicate}"})

    graph = {job['name']: set(job['deps']) for job in jobs}
    in_degree = {job['name']: sum(1 for dep in graph if job['name'] in graph[dep]) for job in jobs}
    queue = [job for job in jobs if in_degree[job['name']] == 0]
    result = []

    while queue:
        job = queue.pop(0)
        result.append(job['name'])
        for dep in graph[job['name']]:
            in_degree[dep] -= 1
            if in_degree[dep] == 0:
                queue.append({'name': dep, 'deps': []})

    if len(result) != len(jobs):
        return Err({"ok": False, "error": "cycle detected"})

    return Ok({"ok": True, "value": result})

