def eval_expr(s: str) -> Ok[int] | Err:
    s = s.replace(" ", "")
    try:
        result, s = parse_expr(s)
        if s:
            return Err(ok=False, error="unexpected end")
        return Ok(ok=True, value=result)
    except SyntaxError as e:
        return Err(ok=False, error=f"unexpected character: {e}")

def parse_expr(s: str) -> tuple[int, str]:
    result, s = parse_term(s)
    while s and s[0] in "+-":
        op, s = s[0], s[1:]
        next_result, s = parse_term(s)
        if op == "+":
            result += next_result
        else:
            result -= next_result
    return result, s

def parse_term(s: str) -> tuple[int, str]:
    result, s = parse_factor(s)
    while s and s[0] in "*/":
        op, s = s[0], s[1:]
        next_result, s = parse_factor(s)
        if op == "*":
            result *= next_result
        else:
            if next_result == 0:
                raise SyntaxError("division by zero")
            result //= next_result
    return result, s

def parse_factor(s: str) -> tuple[int, str]:
    if s[0] == "(":
        s = s[1:]
        result, s = parse_expr(s)
        if s[0] != ")":
            raise SyntaxError("expected closing parenthesis")
        return result, s[1:]
    else:
        end = 0
        while end < len(s) and s[end].isdigit():
            end += 1
        if end == 0:
            raise SyntaxError("expected number or parenthesis")
        return int(s[:end]), s[end:]

