def league_table(matches: list[Match]) -> list[tuple[str, int, int, int]]:
    table = {}
    for match in matches:
        for team, goals in [(match['home'], match['home_goals']), (match['away'], match['away_goals'])]:
            if team not in table:
                table[team] = {'points': 0, 'goals_for': 0, 'goals_against': 0}
            table[team]['goals_for'] += goals
            table[team]['goals_against'] += match['home_goals'] if team == match['away'] else match['away_goals']
            if goals > match['home_goals'] if team == match['away'] else match['away_goals']:
                table[team]['points'] += 3
            elif goals == match['home_goals'] if team == match['away'] else match['away_goals']:
                table[team]['points'] += 1
    return sorted([(team, data['points'], data['goals_for'] - data['goals_against'], data['goals_for']) for team, data in table.items()], key=lambda x: (-x[1], -x[2], -x[3], x[0]))

