def flatten_nested(s: str) -> Ok[tuple[list[int], int]] | Err:
    s = s.replace(" ", "")
    stack: list[list[int]] = []
    result: list[int] = []
    depth = 0
    max_depth = 0
    i = 0

    while i < len(s):
        if s[i] == '[':
            stack.append([])
            depth += 1
            max_depth = max(max_depth, depth)
        elif s[i] == ']':
            if not stack:
                return Err({"ok": False, "error": f"invalid at {i}"})
            current = stack.pop()
            if stack:
                stack[-1].extend(current)
            else:
                result.extend(current)
            depth -= 1
        elif s[i] == ',':
            if not stack:
                return Err({"ok": False, "error": f"invalid at {i}"})
        elif s[i].isdigit() or s[i] == '-':
            j = i
            while j < len(s) and (s[j].isdigit() or s[j] == '-'):
                j += 1
            num = int(s[i:j])
            if stack:
                stack[-1].append(num)
            else:
                result.append(num)
            i = j - 1
        else:
            return Err({"ok": False, "error": f"invalid at {i}"})
        i += 1

    if stack:
        return Err({"ok": False, "error": f"invalid at {i}"})

    return Ok({"ok": True, "value": (result, max_depth)})

from __future__ import annotations

def life_step(grid: list[str], steps: int) -> list[str]:
    def count_live_neighbors(grid: list[str], row: int, col: int) -> int:
        count = 0
        rows, cols = len(grid), len(grid[0])
        for i in range(max(0, row-1), min(rows, row+2)):
            for j in range(max(0, col-1), min(cols, col+2)):
                if (i, j) != (row, col) and grid[i][j] == '#':
                    count += 1
        return count

    def next_generation(grid: list[str]) -> list[str]:
        new_grid = ['' for _ in grid]
        for i in range(len(grid)):
            for j in range(len(grid[0])):
                live_neighbors = count_live_neighbors(grid, i, j)
                if (grid[i][j] == '#' and (live_neighbors == 2 or live_neighbors == 3)) or (grid[i][j] == '.' and live_neighbors == 3):
                    new_grid[i] += '#'
                else:
                    new_grid[i] += '.'
        return new_grid

    for _ in range(steps):
        grid = next_generation(grid)
    return grid

from __future__ import annotations

def lis_length(xs: list[int]) -> tuple[int, int]:
    if not xs:
        return (0, 0)

    n = len(xs)
    lengths = [1] * n
    counts = [1] * n

    for i in range(1, n):
        for j in range(i):
            if xs[i] > xs[j]:
                if lengths[j] + 1 > lengths[i]:
                    lengths[i] = lengths[j] + 1
                    counts[i] = counts[j]
                elif lengths[j] + 1 == lengths[i]:
                    counts[i] += counts[j]

    max_length = max(lengths)
    total_count = sum(counts[i] for i in range(n) if lengths[i] == max_length)

    return (max_length, total_count)

