def invoice_total(lines: list[Line], coupon: str) -> Ok[int] | Err:
    if not lines:
        return Ok(value=0)

    for line in lines:
        if line["qty"] < 1:
            return Err(error=f"bad quantity: {line['sku']}")

    subtotal = 0
    for line in lines:
        amount = line["qty"] * line["unit_cents"]
        if line["qty"] >= 10:
            amount -= amount // 10
        subtotal += amount

    if coupon == "":
        discount = 0
    elif coupon == "SAVE500":
        discount = 500
    elif coupon == "PCT10":
        discount = subtotal // 10
    elif coupon == "BIG20":
        if subtotal >= 10000:
            discount = subtotal // 5
        else:
            return Err(error="coupon not applicable: BIG20")
    else:
        return Err(error=f"unknown coupon: {coupon}")

    amount_after_coupon = max(subtotal - discount, 0)
    tax = (amount_after_coupon * 8 + 50) // 100
    total = amount_after_coupon + tax

    return Ok(value=total)

