def order_states(events: list[OrderEvent]) -> Ok[list[tuple[str, str]]] | Err:
    orders = {}
    for event in events:
        if event["kind"] == "Create":
            if event["id"] in orders:
                return Err(ok=False, error=f"duplicate order: {event['id']}")
            orders[event["id"]] = "created"
        elif event["kind"] == "Pay":
            if event["id"] not in orders:
                return Err(ok=False, error=f"unknown order: {event['id']}")
            if orders[event["id"]] != "created":
                return Err(ok=False, error=f"cannot pay {event['id']} from {orders[event['id']]}")
            orders[event["id"]] = "paid"
        elif event["kind"] == "Ship":
            if event["id"] not in orders:
                return Err(ok=False, error=f"unknown order: {event['id']}")
            if orders[event["id"]] != "paid":
                return Err(ok=False, error=f"cannot ship {event['id']} from {orders[event['id']]}")
            orders[event["id"]] = "shipped"
        elif event["kind"] == "Cancel":
            if event["id"] not in orders:
                return Err(ok=False, error=f"unknown order: {event['id']}")
            if orders[event["id"]] not in ["created", "paid"]:
                return Err(ok=False, error=f"cannot cancel {event['id']} from {orders[event['id']]}")
            orders[event["id"]] = "cancelled"
    return Ok(ok=True, value=sorted(orders.items()))

