from __future__ import annotations

def min_coins(coins: list[int], amount: int) -> tuple[int, list[int]] | None:
    if amount < 0:
        return None
    if amount == 0:
        return 0, []

    coins.sort(reverse=True)
    dp: list[tuple[int, list[int]] | None] = [None] * (amount + 1)
    dp[0] = (0, [])

    for i in range(1, amount + 1):
        min_coins = float('inf')
        best_combination: list[int] | None = None
        for coin in coins:
            if i - coin >= 0 and dp[i - coin] is not None:
                if dp[i - coin][0] + 1 < min_coins or (dp[i - coin][0] + 1 == min_coins and (best_combination is None or dp[i - coin][1] > best_combination)):
                    min_coins = dp[i - coin][0] + 1
                    best_combination = dp[i - coin][1] + [coin]
        dp[i] = (min_coins, best_combination)

    return dp[amount]

