def parse_query(s: str) -> Ok[list[tuple[str, str]]] | Err:
    items = [item for item in s.split('&') if item]
    pairs = []
    for item in items:
        key, *value_parts = item.split('=')
        key = key.replace('+', ' ')
        if not key:
            return Err(ok=False, error=f"empty key: {item}")
        value = '='.join(value_parts).replace('+', ' ')
        pairs.append((key, value))
    return Ok(ok=True, value=pairs)

