def pig_latin(s: str) -> str:
    def translate(word: str) -> str:
        vowels = "aeiou"
        if word[0] in vowels:
            return word + "way"
        for i, char in enumerate(word):
            if char in vowels and (i == 0 or word[i-1] != 'q'):
                return word[i:] + word[:i] + "ay"
        return word + "ay"

    return " ".join(translate(word) for word in s.split())

# Rationale:
# - The function `pig_latin` takes a string `s` and returns a string where each word is translated to Pig Latin.
# - The helper function `translate` handles the translation of a single word.
# - The main function splits the input string into words, translates each word using `translate`, and joins them back into a single string.

