def rle_decode(s: str) -> Ok[str] | Err:
    result = []
    i = 0
    while i < len(s):
        if s[i].isdigit():
            return Err(ok=False, error="missing character before count")
        char = s[i]
        i += 1
        count = ""
        while i < len(s) and s[i].isdigit():
            count += s[i]
            i += 1
        if count == "":
            result.append(char)
        elif count.startswith("0"):
            return Err(ok=False, error=f"bad count for {char}")
        else:
            result.extend([char] * int(count))
    return Ok(ok=True, value="".join(result))

