from typing import TypedDict

class Contact(TypedDict):
    name: str
    email: str
    phone: str

def merge_contacts(contacts: list[Contact]) -> list[Contact]:
    if not contacts:
        return []

    # Helper function to clean email and phone
    def clean_email(email: str) -> str:
        return email.strip()

    def clean_phone(phone: str) -> str:
        return ''.join(filter(str.isdigit, phone))

    # Create a dictionary to map cleaned emails and phones to their indices
    email_map: dict[str, int] = {}
    phone_map: dict[str, int] = {}

    for i, contact in enumerate(contacts):
        cleaned_email = clean_email(contact['email'])
        cleaned_phone = clean_phone(contact['phone'])

        if cleaned_email:
            email_map[cleaned_email] = i
        if cleaned_phone:
            phone_map[cleaned_phone] = i

    # Create a list to store the merged contacts
    merged_contacts: list[Contact] = contacts.copy()

    # Traverse the contacts to merge them
    for i, contact in enumerate(contacts):
        if i in email_map or i in phone_map:
            continue

        merged_contact = merged_contacts[i]
        for j in range(i + 1, len(contacts)):
            other_contact = contacts[j]
            other_cleaned_email = clean_email(other_contact['email'])
            other_cleaned_phone = clean_phone(other_contact['phone'])

            if other_cleaned_email and other_cleaned_email in email_map:
                email_map[other_cleaned_email] = i
                merged_contact['name'] = other_contact['name'] if other_contact['name'] else merged_contact['name']
                merged_contact['email'] = other_contact['email'] if other_contact['email'] else merged_contact['email']
                merged_contact['phone'] = other_contact['phone'] if other_contact['phone'] else merged_contact['phone']
                break

            if other_cleaned_phone and other_cleaned_phone in phone_map:
                phone_map[other_cleaned_phone] = i
                merged_contact['name'] = other_contact['name'] if other_contact['name'] else merged_contact['name']
                merged_contact['email'] = other_contact['email'] if other_contact['email'] else merged_contact['email']
                merged_contact['phone'] = other_contact['phone'] if other_contact['phone'] else merged_contact['phone']
                break

    return merged_contacts

