class Session(TypedDict):
    user: str
    kind: str
    time: int

def session_totals(events: list[Session]) -> list[tuple[str, int]]:
    user_sessions = {}
    for event in events:
        user = event['user']
        if event['kind'] == 'login':
            if user not in user_sessions:
                user_sessions[user] = event['time']
        elif event['kind'] == 'logout':
            if user in user_sessions:
                total = event['time'] - user_sessions[user]
                if user in user_sessions:
                    user_sessions[user] += total
                else:
                    user_sessions[user] = total
    result = [(user, total) for user, total in user_sessions.items()]
    result.sort(key=lambda x: x[0])
    return result

