from typing import Literal, TypedDict

class Forward(TypedDict):
    kind: Literal["Forward"]
    steps: int

class TurnLeft(TypedDict):
    kind: Literal["TurnLeft"]

class TurnRight(TypedDict):
    kind: Literal["TurnRight"]

Cmd = Forward | TurnLeft | TurnRight

def robot_walk(cmds: list[Cmd], obstacles: list[tuple[int, int]]) -> tuple[int, int, str]:
    x, y = 0, 0
    direction = "N"
    dx, dy = 0, 1  # Initial direction is North

    for cmd in cmds:
        if cmd["kind"] == "TurnLeft":
            dx, dy = -dy, dx  # Rotate left
            if direction == "N":
                direction = "W"
            elif direction == "E":
                direction = "N"
            elif direction == "S":
                direction = "E"
            elif direction == "W":
                direction = "S"
        elif cmd["kind"] == "TurnRight":
            dx, dy = dy, -dx  # Rotate right
            if direction == "N":
                direction = "E"
            elif direction == "E":
                direction = "S"
            elif direction == "S":
                direction = "W"
            elif direction == "W":
                direction = "N"
        elif cmd["kind"] == "Forward":
            for _ in range(cmd["steps"]):
                nx, ny = x + dx, y + dy
                if (nx, ny) not in obstacles:
                    x, y = nx, ny
                else:
                    break

    return (x, y, direction)

