def roman_to_int(s: str) -> Ok[int] | Err:
    if not s:
        return Err(ok=False, error="empty")

    roman_map = {
        'I': 1, 'V': 5, 'X': 10, 'L': 50, 'C': 100, 'D': 500, 'M': 1000,
        'IV': 4, 'IX': 9, 'XL': 40, 'XC': 90, 'CD': 400, 'CM': 900
    }

    i, n = 0, len(s)
    result = 0

    while i < n:
        if i + 1 < n and s[i:i+2] in roman_map:
            result += roman_map[s[i:i+2]]
            i += 2
        elif s[i] in roman_map:
            result += roman_map[s[i]]
            i += 1
        else:
            return Err(ok=False, error=f"invalid character: {s[i]}")

    if not (1 <= result <= 3999):
        return Err(ok=False, error="not canonical")

    return Ok(ok=True, value=result)

