def spiral_order(m: list[list[int]]) -> list[int]:
    if not m or not m[0]:
        return []

    result = []
    while m:
        # Top row
        result.extend(m.pop(0))
        # Right column
        if m and m[0]:
            for row in m:
                result.append(row.pop())
        # Bottom row
        if m:
            result.extend(m.pop()[::-1])
        # Left column
        if m and m[0]:
            for row in m[::-1]:
                result.append(row.pop(0))
    return result

