class Student(TypedDict):
    name: str
    scores: list[int]

def student_medians(students: list[Student]) -> list[tuple[str, float]]:
    def median(scores: list[int]) -> float:
        sorted_scores = sorted(scores)
        n = len(sorted_scores)
        mid = n // 2
        if n % 2 == 0:
            return (sorted_scores[mid - 1] + sorted_scores[mid]) / 2.0
        else:
            return sorted_scores[mid]

    medians = [(student['name'], median(student['scores'])) for student in students if student['scores']]
    return sorted(medians, key=lambda x: (-x[1], x[0]))

