def tennis_score(points: str) -> str:
    score = {"A": 0, "B": 0}
    for point in points:
        if point not in "AB":
            return "error: bad point"
        score[point] += 1
        if score[point] >= 4 and score[point] - score["A" if point == "B" else "B"] >= 2:
            return f"game {point}"
    if score["A"] >= 3 and score["B"] >= 3:
        if score["A"] == score["B"]:
            return "deuce"
        return f"advantage {'A' if score['A'] > score['B'] else 'B'}"
    return f"{score['A'] if score['A'] < 4 else 'love'}-{score['B'] if score['B'] < 4 else 'love'}"

