    kind: Literal["Undo"]

EditOp = Insert | Delete | Left | Right | Undo

def text_editor(ops: list[EditOp]) -> str:
    text = ""
    cursor = 0
    history: list[tuple[str, int]] = []

    for op in ops:
        if op["kind"] == "Insert":
            history.append((text, cursor))
            text = text[:cursor] + op["text"] + text[cursor:]
            cursor += len(op["text"])
        elif op["kind"] == "Delete":
            history.append((text, cursor))
            n = min(op["n"], cursor)
            text = text[:cursor - n] + text[cursor:]
            cursor -= n
        elif op["kind"] == "Left":
            history.append((text, cursor))
            cursor = max(0, cursor - op["n"])
        elif op["kind"] == "Right":
            history.append((text, cursor))
            cursor = min(len(text), cursor + op["n"])
        elif op["kind"] == "Undo":
            if history:
                text, cursor = history.pop()

    return text

from __future__ import annotations

def tic_tac_toe(board: list[str]) -> str:
    def has_line(player: str) -> bool:
        # Check rows, columns, and diagonals
        for i in range(3):
            if all(board[i][j] == player for j in range(3)) or \
               all(board[j][i] == player for j in range(3)):
                return True
        if board[0][0] == board[1][1] == board[2][2] == player or \
           board[0][2] == board[1][1] == board[2][0] == player:
            return True
        return False

    x_count = sum(row.count('X') for row in board)
    o_count = sum(row.count('O') for row in board)

    if abs(x_count - o_count) > 1:
        return "invalid"

    if has_line('X') and x_count != o_count + 1:
        return "invalid"
    if has_line('O') and x_count != o_count:
        return "invalid"

    if has_line('X'):
        return "X wins"
    if has_line('O'):
        return "O wins"
    if all('.' not in row for row in board):
        return "draw"
    return "in progress"

