def poker_hand(cards: list[str]) -> str:
    if len(cards) != 5:
        return "invalid"
    if len(set(cards)) != 5:
        return "invalid"
    ranks = sorted([rank_map[card[0]] for card in cards])
    suits = [card[1] for card in cards]
    if all(suit == suits[0] for suit in suits):
        if is_straight(ranks):
            return "straight flush"
        else:
            return "flush"
    if is_straight(ranks):
        return "straight"
    rank_counts = sorted([ranks.count(rank) for rank in set(ranks)])
    if rank_counts == [1, 1, 1, 2, 2]:
        return "full house"
    if rank_counts == [1, 2, 3]:
        return "three of a kind"
    if rank_counts == [1, 2, 2]:
        return "two pair"
    if rank_counts == [1, 1, 2, 2]:
        return "one pair"
    return "high card"

