    kind: Literal["Sym"]
    text: str

Token = Num | Ident | Sym

def tokenize(s: str) -> Ok[list[Token]] | Err:
    tokens: list[Token] = []
    i = 0
    while i < len(s):
        if s[i].isspace():
            i += 1
        elif s[i].isdigit():
            start = i
            while i < len(s) and s[i].isdigit():
                i += 1
            tokens.append(Num(kind="Num", value=int(s[start:i])))
        elif s[i].islower() or s[i] == '_':
            start = i
            while i < len(s) and (s[i].islower() or s[i].isdigit() or s[i] == '_'):
                i += 1
            tokens.append(Ident(kind="Ident", name=s[start:i]))
        elif s[i:i+2] in ("==", "<=", ">=", "!="):
            tokens.append(Sym(kind="Sym", text=s[i:i+2]))
            i += 2
        elif s[i] in "+-*/=<>(),":
            tokens.append(Sym(kind="Sym", text=s[i]))
            i += 1
        else:
            return Err(ok=False, error=f"unexpected character: {s[i]} at {i}")
    return Ok(ok=True, value=tokens)

